// Question banks: quantum, bonding, stoich, thermo1, thermo2, equilibrium.
// Convention: 5 warm-ups then CCC/CCO/USNCO style; every bank here except
// thermo2 opens with 10 Basics (tier 1) instead.
import type { QuizQ } from './framework';

export const QUANTUM_QUIZ: QuizQ[] = [
  // ---- 1-10 Basics ----
  { id: 'qua-001', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'What is the maximum number of electrons in a p subshell?', opts: ['6', '4', '2', '10'], a: 0, why: 'This is asking how many electrons fit in one p subshell. A subshell is a set of orbitals of the same shape, and each orbital holds two electrons. A p subshell has three orbitals, so 3 × 2 = 6.' },
  { id: 'qua-002', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which orbital is spherical?', opts: ['p', 's', 'd', 'f'], a: 1, why: 'This is asking which orbital shape is a sphere. An orbital is the region where an electron is likely to be found. The s orbital is a sphere, p orbitals are dumbbells, and most d orbitals have four lobes.' },
  { id: 'qua-003', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many orbitals are in the n = 2 shell?', opts: ['1', '2', '4', '8'], a: 2, why: 'This is asking how many orbitals share the shell n = 2. A shell holds n² orbitals, here one 2s plus three 2p. So 2² = 4 orbitals, together holding up to 8 electrons.' },
  { id: 'qua-004', topic: 'quantum', skill: 'atomic/configuration', q: 'What is the ground-state electron configuration of sodium (11 electrons)?', opts: ['[Ar]4s¹', '[Ne]3p¹', '[He]2s²2p⁶3s²', '[Ne]3s¹'], a: 3, why: 'This is asking how sodium\'s 11 electrons are arranged. Electrons fill the lowest-energy orbitals first. Ten of them complete 1s²2s²2p⁶, the neon core, so the eleventh goes into 3s.' },
  { id: 'qua-005', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which quantum number determines the SHAPE of an orbital?', opts: ['ℓ', 'n', 'mℓ', 'ms'], a: 0, why: 'This is asking which of the four quantum numbers controls orbital shape. ℓ, the angular momentum quantum number, sets the shape: ℓ = 0 is a sphere (s), ℓ = 1 a dumbbell (p). The other three set size (n), direction (mℓ) and spin (ms).' },
  { id: 'qua-026', tier: 1, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many electrons can the n = 3 shell hold in total?', opts: ['9', '6', '32', '18'], a: 3, why: 'This is asking for the electron capacity of a whole shell. A shell numbered n holds n² orbitals, and every orbital holds at most two electrons. So n = 3 has 3² = 9 orbitals, and 9 × 2 = 18 electrons.', misconception: 'The orbital count and the electron count are different numbers, and n² gives the first one. Shell 3 has 9 orbitals but 18 electrons, because each orbital takes a pair. Answering 9 means stopping one step early; the capacity is always 2n².' },
  { id: 'qua-027', tier: 1, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many orbitals are in a d subshell?', opts: ['5', '3', '7', '10'], a: 0, why: 'This is asking how many orbitals share one d subshell. A subshell is a set of orbitals of the same shape, and each one holds at most two electrons. A full d subshell holds 10 electrons, so it must contain 10 ÷ 2 = 5 orbitals.', misconception: 'Ten is the electron capacity of the d subshell, not its orbital count. The same slip is easy on p: three orbitals, six electrons. Divide the capacity by two whenever the question asks for orbitals.' },
  { id: 'qua-028', tier: 1, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which values may mℓ take when ℓ = 1?', opts: ['0 only', '−1, 0, +1', '−½ and +½', '1, 2 and 3'], a: 1, why: 'This is asking how many directions an orbital of this shape can point. mℓ, the magnetic quantum number, runs in whole steps from −ℓ up to +ℓ. With ℓ = 1 that gives −1, 0 and +1, which is why there are three p orbitals at right angles.' },
  { id: 'qua-029', tier: 1, topic: 'quantum', skill: 'atomic/configuration', q: 'What is the ground-state electron configuration of oxygen (8 electrons)?', opts: ['1s²2s⁴2p²', '1s²2s²2p⁶', '1s²2s²2p⁴', '1s²2s²2p³3s¹'], a: 2, why: 'This is asking how oxygen\'s eight electrons are arranged. Electrons fill the lowest-energy orbitals first, and each subshell takes only what it can hold: 2 in s, 6 in p. Two go into 1s, two into 2s, and the last four into 2p, giving 1s²2s²2p⁴.' },
  { id: 'qua-030', tier: 1, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many nodes does a 2p orbital have, and of what kind?', opts: ['one, a flat plane through the nucleus', 'none at all', 'one, a spherical shell inside it', 'two, one plane and one sphere'], a: 0, why: 'This is asking where a 2p electron is never found. A node is a surface on which the chance of finding the electron drops to zero. A p orbital is two lobes on opposite sides of the nucleus, and the flat plane separating them is its one node.', misconception: '2s and 2p both have exactly one node, but the two nodes are different shapes and get swapped constantly. The 2s node is a hollow sphere inside the orbital; the 2p node is a flat plane through the nucleus. Picture the orbital before counting: a sphere cannot be split by a plane, and a dumbbell is not split by a shell.' },
  // ---- 11-20 Core ----
  { id: 'qua-033', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'Which subshell fills BEFORE the 3d subshell?', opts: ['3f', '4s', '4p', '5s'], a: 1, why: 'This is asking about the one place the filling order departs from the shell numbers. Electrons enter the lowest-energy orbital available, and 4s lies slightly below 3d in energy. So potassium and calcium fill 4s first, and only then does the 3d set fill across the ten transition metals.', misconception: 'The belief to drop is that a shell must be finished before the next one starts. Shell numbers order the sizes, not the energies, and 4s dips below 3d — which is why the fourth row of the table opens with two s-block elements before the d block begins. There is no 3f subshell at all: shell 3 stops at d.' },
  { id: 'qua-031', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'What is the ground-state electron configuration of a bromine atom (35 electrons)?', opts: ['[Ar]3d¹⁰4s²4p³', '[Ar]4s²4p⁵', '[Ar]3d⁹4s²4p⁶', '[Ar]3d¹⁰4s²4p⁵'], a: 3, why: 'This is asking you to fill the orbitals in order until all 35 electrons are placed. Electrons enter the lowest available orbital first, and past argon the order runs 4s, then 3d, then 4p. Argon accounts for 18, so 2 more fill 4s, 10 fill 3d and the last 5 go into 4p, giving [Ar]3d¹⁰4s²4p⁵ — and 18 + 10 + 2 + 5 = 35 checks it.', misconception: 'The belief to drop is that the d subshell can be skipped because bromine is not a transition metal. Those ten 3d electrons are really there; they simply sit below the outer shell and take no part in bonding. Leaving them out gives [Ar]4s²4p⁵, which accounts for only 25 electrons.' },
  { id: 'qua-034', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'An element has the outer configuration 3s²3p². Which block of the periodic table is it in, and which period?', opts: ['the p block, period 3', 'the s block, period 3', 'the p block, period 2', 'the d block, period 3'], a: 0, why: 'This is asking you to read a position off a configuration. The period number is the highest shell present, which is 3 here. The block is named after the subshell the last electron entered, and that is a p subshell, so the element sits in the p block of period 3 — it is silicon.', misconception: 'The belief to drop is that the block follows from the number of outer electrons. Four outer electrons might suggest the fourth column, but the s and p subshells are read together and 3s²3p² lands in the fourteenth. Look at which subshell the last electron entered.' },
  { id: 'qua-032', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'How many valence electrons does a sulfur atom have?', opts: ['16', '4', '6', '2'], a: 2, why: 'This is asking how many electrons sit in the outermost shell. Sulfur is [Ne]3s²3p⁴, so its highest shell, n = 3, holds 2 + 4 = 6 electrons. For a main-group element the group number gives the same count directly: group 16 means 16 − 10 = 6.', misconception: 'The belief to drop is that the valence count is the atom\'s total number of electrons. Sulfur has 16 electrons altogether, but 10 of them are the neon core and take no part in bonding. Only the outermost shell counts, which is why groups 13 to 18 need the group number minus 10.' },
  { id: 'qua-038', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'How many core electrons does a potassium atom (19 electrons) have?', opts: ['18', '19', '1', '8'], a: 0, why: 'This is asking you to split an atom\'s electrons into the outermost shell and everything below it. Potassium is [Ar]4s¹, so its highest shell, n = 4, holds a single electron, and that one is the valence electron. The other 18 make up the argon core.', misconception: 'The belief to drop is that the core is only the innermost shell. Everything below the outermost shell counts as core, so potassium\'s core is the whole argon arrangement of 18 electrons rather than just the two in 1s. The valence count is what the group number gives, and group 1 gives one.' },
  { id: 'qua-035', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'What is the electron configuration of the chloride ion, Cl⁻?', opts: ['[Ne]3s²3p⁴', '[Ne]3s²3p⁵', '[Ne]3s¹3p⁶', '[Ne]3s²3p⁶'], a: 3, why: 'This is asking what changes when an atom gains an electron. A chlorine atom is [Ne]3s²3p⁵, with one space left in its 3p subshell. Adding one electron fills that space, giving [Ne]3s²3p⁶ — the same arrangement as an argon atom.', misconception: 'The belief to drop is that the minus sign means an electron has been removed. A negative charge records a surplus of electrons, so Cl⁻ holds 18 against chlorine\'s 17. Positive ions are the ones that have lost electrons.' },
  { id: 'qua-013', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'What is the electron configuration of the Fe²⁺ ion?', opts: ['[Ar]4s²3d⁴', '[Ar]3d⁵', '[Ar]4s¹3d⁵', '[Ar]3d⁶'], a: 3, why: 'This is asking which electrons leave when a transition metal forms an ion. An iron atom is [Ar]3d⁶4s², and a positive ion loses electrons from the outermost shell, which is n = 4. So the two 4s electrons go first and Fe²⁺ is [Ar]3d⁶.', misconception: 'The belief to drop is that the electrons which filled last are the ones removed first. The 4s subshell does fill before 3d, but once 3d is occupied it drops below 4s in energy, so the 4s pair is the outermost and leaves first. Taking the electrons out of 3d instead gives [Ar]4s²3d⁴, which is not what iron forms.' },
  { id: 'qua-024', tier: 2, topic: 'quantum', skill: 'atomic/configuration', q: 'Which of these does NOT have the same number of electrons as the other three?', opts: ['Ar', 'Na⁺', 'Cl⁻', 'K⁺'], a: 1, why: 'This is asking you to count the electrons on each particle. Start from the neutral atom and adjust for the charge: argon has 18, K⁺ is 19 − 1 = 18 and Cl⁻ is 17 + 1 = 18. Na⁺ is 11 − 1 = 10, which matches neon instead, so it is the odd one out.', misconception: 'The belief to drop is that ions written near each other in the table must hold the same number of electrons. What decides it is the atom\'s own electron count adjusted by the charge, and sodium starts six electrons short of argon. Count each particle separately rather than grouping them by where they sit.' },
  { id: 'qua-036', tier: 2, topic: 'quantum', skill: 'atomic/spectra', q: 'A sodium lamp emits light of wavelength 589 nm. What is the energy of one of its photons? (h = 6.626 × 10⁻³⁴ J·s, c = 2.998 × 10⁸ m/s)', opts: ['3.37 × 10⁻²² J', '1.17 × 10⁻²⁷ J', '3.37 × 10⁻¹⁹ J', '5.09 × 10¹⁴ J'], a: 2, why: 'This is asking you to turn a wavelength into an energy per photon. Light arrives in packets called photons, and one photon carries E = hc ÷ λ with the wavelength in metres. Here 589 nm is 589 × 10⁻⁹ m, so E = (6.626 × 10⁻³⁴ × 2.998 × 10⁸) ÷ (589 × 10⁻⁹) = 3.37 × 10⁻¹⁹ J.', misconception: 'The belief to drop is that a wavelength in nanometres can go straight into the formula. Every quantity in E = hc ÷ λ is in SI units, so 589 must first become 589 × 10⁻⁹ m; leaving it as 589 shifts the answer by nine powers of ten. A photon of visible light always comes out near 10⁻¹⁹ J, which is a useful check.' },
  { id: 'qua-037', tier: 2, topic: 'quantum', skill: 'atomic/spectra', q: 'Sodium vapour emits light at 589 nm. Which wavelength does the same vapour absorb most strongly out of white light?', opts: ['a wavelength twice as long, 1178 nm', '589 nm, the same wavelength', 'any wavelength shorter than 589 nm', 'none — a gas that emits light cannot absorb it'], a: 1, why: 'This is asking whether absorbing and emitting use the same energy gap. An electron may only sit at certain energies, so an atom absorbs a photon only when that photon matches a gap exactly. The electron falls back across that same gap later and emits a photon of the same energy, so the two wavelengths are identical.', misconception: 'The belief to drop is that absorbing and emitting are separate processes with separate wavelengths. They are one jump taken in opposite directions, which is why the dark lines in sunlight sit at exactly the wavelengths a hot gas of the same element gives out.' },
  // ---- 21+ Contest ----
  { id: 'qua-006', tier: 3, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many radial nodes does a 4d orbital have?', opts: ['0', '1', '2', '3'], a: 1, why: 'Radial nodes = n − ℓ − 1 = 4 − 2 − 1 = <b>1</b>. (Angular nodes = ℓ = 2, total = n − 1 = 3.)', misconception: 'There are three different node counts and they are easy to swap. Total nodes = n − 1, angular (planar) nodes = ℓ, and radial (spherical) nodes = n − ℓ − 1. A 4d orbital has 3 total, 2 angular and only 1 radial. Answering "2" or "3" here almost always means quoting one of the other two counts, so write all three down before choosing.' },
  { id: 'qua-007', tier: 3, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which quantum number set is IMPOSSIBLE?', opts: ['n=3, ℓ=2, mℓ=−2', 'n=4, ℓ=0, mℓ=0', 'n=2, ℓ=2, mℓ=0', 'n=5, ℓ=3, mℓ=3'], a: 2, why: 'ℓ can only go up to n−1, so n=2 allows ℓ = 0 or 1 only. "2d" orbitals don\'t exist.' },
  { id: 'qua-008', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Why is the first ionization energy of O slightly LOWER than N?', opts: ['O is larger than N', 'O has more shielding electrons', 'N has a full 2p subshell', 'pairing repulsion in O\'s 2p⁴'], a: 3, why: 'N is 2p³ (half-filled, all unpaired). O\'s fourth 2p electron must pair up — that repulsion makes it easier to remove.', misconception: 'Ionisation energy does not rise monotonically across a period — it steps back twice, and both dips are about electron configuration rather than size. B (2s²2p¹) is easier to ionise than Be because the 2p electron is higher in energy than the filled 2s; O (2p⁴) is easier than N because its fourth 2p electron must pair in an already-occupied orbital and pays the repulsion. Reaching for "O is bigger" is the trend answer, and it is the wrong mechanism.' },
  { id: 'qua-009', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Largest radius in the isoelectronic series O²⁻, F⁻, Na⁺, Mg²⁺?', opts: ['O²⁻', 'F⁻', 'Na⁺', 'Mg²⁺'], a: 0, why: 'All have 10 electrons; O²⁻ has the fewest protons (8) pulling them in, so it\'s the largest.' },
  { id: 'qua-010', tier: 3, topic: 'quantum', skill: 'atomic/spectra', q: 'The n=3 → n=2 transition in hydrogen emits light at about…', opts: ['122 nm (UV)', '486 nm (blue-green)', '656 nm (red)', '1875 nm (IR)'], a: 2, why: 'Balmer series, first line: ΔE = 13.6(1/4 − 1/9) = 1.89 eV → λ = 1240/1.89 ≈ <b>656 nm</b>, the H-α red line.', misconception: 'The series is named for the LOWER level, not the upper one: transitions ending at n = 1 are Lyman (UV, 122 nm), at n = 2 Balmer (visible), at n = 3 Paschen (IR, 1875 nm). Within Balmer, 3 → 2 is the smallest energy gap and therefore the LONGEST wavelength, 656 nm red; 486 nm blue-green is 4 → 2. Picking 486 usually means counting the visible lines from the blue end, or assuming the first line of a series is the most energetic one.' },
  { id: 'qua-011', tier: 3, topic: 'quantum', skill: 'atomic/pes', q: 'In the PES spectrum of neon, the peak at HIGHEST binding energy corresponds to…', opts: ['2p electrons', '1s electrons', '2s electrons', 'valence electrons'], a: 1, why: 'Core 1s electrons sit closest to the nucleus and need the most energy to remove — they appear at the highest ionization energy.' },
  { id: 'qua-012', tier: 3, topic: 'quantum', skill: 'atomic/configuration', q: 'Number of unpaired electrons in ground-state Cr (Z = 24)?', opts: ['6', '5', '4', '2'], a: 0, why: 'Cr is the exception: [Ar]4s¹3d⁵ — one unpaired 4s plus five unpaired 3d = <b>6</b>.', misconception: 'Cr and Cu are not exceptions you can derive from the aufbau order — they are exceptions <em>to</em> it, and they must be known. Cr is [Ar]4s¹3d⁵ and Cu is [Ar]4s¹3d¹⁰, because a half-filled or filled d set plus a half-filled 4s beats the naive 4s²3d⁴ / 4s²3d⁹. Filling by the diagonal rule without checking for these two is what produces the "4 unpaired" answer.' },
  { id: 'qua-014', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Which element shows the biggest jump between its 1st and 2nd ionization energies?', opts: ['Mg', 'Al', 'Na', 'Si'], a: 2, why: 'After losing one electron Na⁺ has a noble-gas core — ripping the second electron out of that core costs ~10× more. The jump position identifies the group.' },
  { id: 'qua-015', tier: 3, topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'An electron and a proton move at the same speed. The electron\'s de Broglie wavelength is…', opts: ['shorter', 'about 1800× longer', 'the same', 'zero'], a: 1, why: 'λ = h/mv — the electron\'s mass is ~1836× smaller, so its wavelength is ~1836× longer at equal speed.', misconception: 'λ = h/mv puts mass in the <em>denominator</em>: at the same speed, the lighter particle has the LONGER wavelength. The intuition that a fast, light electron must be "smaller" in every sense is what produces the "shorter" answer. This is exactly why electron microscopes resolve better than light microscopes — accelerate the electron and you shorten λ, but comparing it with a proton at equal speed, the electron wins by its ~1836× smaller mass.' },
  { id: 'qua-016', tier: 3, topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'In the photoelectric effect, increasing light INTENSITY (same frequency)…', opts: ['ejects more electrons, same KE', 'increases electron KE', 'stops emission', 'increases the work function'], a: 0, why: 'Each photon\'s energy (hν) is unchanged — more photons just eject more electrons. Only frequency raises KE = hν − φ. Treating light as a continuous wave predicts the opposite, which is why the photon picture was needed.', misconception: 'Intensity and frequency do completely different things in the photoelectric effect, and conflating them is what the experiment was built to expose. One photon ejects one electron, so brighter light (more photons per second) ejects more electrons — each still with KE = hν − φ. Only raising the <em>frequency</em> raises the kinetic energy, and below the threshold frequency no intensity at all will eject anything. Classical wave theory predicted the opposite on both counts.' },
  { id: 'qua-017', tier: 3, topic: 'quantum', skill: 'atomic/spectra', q: 'Which hydrogen transition emits the HIGHEST-energy photon?', opts: ['n=4 → n=2', 'n=3 → n=2', 'n=5 → n=3', 'n=2 → n=1'], a: 3, why: 'The 1/n² spacing is hugely lopsided: dropping to n=1 (Lyman) releases more than any transition between higher levels. ΔE = 13.6(1 − ¼) = 10.2 eV.' },
  { id: 'qua-018', tier: 3, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'In the HYDROGEN atom (one electron), which orbitals have the same energy?', opts: ['only orbitals with the same ℓ', '3s < 3p < 3d always', '3s, 3p, and 3d all equal', 'none are degenerate'], a: 2, why: 'With one electron there\'s no shielding — energy depends on n only, so all nine n=3 orbitals are degenerate. Multi-electron atoms split them (s < p < d).', misconception: 'The familiar ns &lt; np &lt; nd ordering is a <em>multi-electron</em> phenomenon, caused by electrons shielding one another unequally. Hydrogen has one electron and nothing to shield it, so its energy depends on n alone and all nine n = 3 orbitals are exactly degenerate. Carrying the "s is always lower" rule into the one-electron atom is the trap.' },
  { id: 'qua-019', tier: 3, topic: 'quantum', skill: 'atomic/pes', q: 'A PES spectrum shows two peaks with area ratio 2:1. The element is…', opts: ['He', 'Li', 'Be', 'B'], a: 1, why: 'Li: 1s²2s¹ → two electrons in one peak, one in another = 2:1. (Be would be 2:2 = 1:1; B gives three peaks.)', misconception: 'Peak COUNT tells you how many occupied subshells there are; peak AREA tells you how many electrons sit in each. Two peaks alone would fit Li or Be equally — only the 2:1 area separates them, since Be (1s²2s²) gives 2:2 and B adds a third peak for its 2p electron. Choosing Be means reading the number of peaks and ignoring their sizes.' },
  { id: 'qua-020', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Which element has the most NEGATIVE (most favorable) electron affinity?', opts: ['F', 'Cl', 'O', 'N'], a: 1, why: 'Chlorine, not fluorine. Fluorine\'s 2p shell is small, so an extra electron arrives crowded and is repelled by the ones already there. Chlorine releases 349 kJ/mol on gaining an electron; fluorine only 328 kJ/mol.', misconception: 'Electron affinity is not simply "the trend continued to fluorine". Cl (−349 kJ/mol) is more exothermic than F (−328): F\'s 2p shell is so compact that an incoming electron pays a large electron–electron repulsion penalty on arrival. The same effect makes O less favourable than S. Nearly every second-period element sits slightly off the trend for this reason.' },
  { id: 'qua-021', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Zeff on the valence electron increases across a period mainly because…', opts: ['n increases', 'shielding increases faster than Z', 'protons are added while shielding stays roughly constant', 'orbitals shrink spontaneously'], a: 2, why: 'Same-shell electrons shield each other poorly (~0.35 each), so each added proton raises the net pull on valence electrons.' },
  { id: 'qua-022', tier: 3, topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Total nodes and radial nodes of a 5f orbital?', opts: ['3 total, 0 radial', '5 total, 2 radial', '4 total, 3 radial', '4 total, 1 radial'], a: 3, why: 'Total = n − 1 = 4; angular = ℓ = 3; radial = n − ℓ − 1 = 1.' },
  { id: 'qua-023', tier: 3, topic: 'quantum', skill: 'atomic/spectra', q: 'Energy needed to ionize a hydrogen atom already excited to n = 2?', opts: ['3.4 eV', '6.8 eV', '13.6 eV', '10.2 eV'], a: 0, why: 'E₂ = −13.6/2² = −3.4 eV, so lifting it to E = 0 takes <b>3.4 eV</b>. One-quarter of the ground-state value.' },
  { id: 'qua-025', tier: 3, topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'The Heisenberg uncertainty principle says that…', opts: ['electrons repel each other', 'energy isn\'t conserved briefly', 'position and momentum can\'t both be known exactly', 'orbitals are exact paths'], a: 2, why: 'Δx·Δp ≥ ħ/2 — this is WHY we speak of orbitals (probability clouds) rather than orbits (paths).' },
];

export const BONDING_QUIZ: QuizQ[] = [
  // ---- 1-10 Basics ----
  { id: 'bon-001', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'How many shared-pair (covalent) bonds does a carbon atom usually form?', opts: ['2', '3', '4', '6'], a: 2, why: 'This is asking how many bonds a carbon atom normally makes. A covalent bond is one pair of electrons shared between two atoms, and an atom shares until it has eight electrons in its outer shell. Carbon starts with four outer electrons, so it needs four more and forms four bonds.' },
  { id: 'bon-002', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'The shape of CO₂ is…', opts: ['bent', 'tetrahedral', 'trigonal planar', 'linear'], a: 3, why: 'This is asking for the shape of CO₂. Groups of electrons around the central atom spread as far apart as they can. Carbon here has two groups, the two C=O double bonds, and no lone pairs. Two groups sit 180° apart, so the molecule is linear.' },
  { id: 'bon-003', topic: 'bonding', skill: 'bonding/bond-properties', q: 'A double bond consists of…', opts: ['1 sigma (σ) + 1 pi (π)', '2 pi (π) bonds', '2 sigma (σ) bonds', '1 sigma (σ) + 2 pi (π)'], a: 0, why: 'This is asking what a double bond is made of. The first bond between two atoms is always a sigma bond, from orbitals overlapping head-on. Any extra bond is a pi bond, from p orbitals overlapping sideways. A double bond is therefore one sigma plus one pi.' },
  { id: 'bon-004', topic: 'bonding', skill: 'bonding/polarity', q: 'A bond between atoms with an electronegativity difference of about 0.5 is best called…', opts: ['nonpolar covalent', 'polar covalent', 'ionic', 'metallic'], a: 1, why: 'This is asking what a small electronegativity difference means. Electronegativity is how strongly an atom pulls shared electrons toward itself. A difference under about 0.4 counts as nonpolar and over about 1.8 as ionic. A gap of 0.5 falls between, so the bond is polar covalent.' },
  { id: 'bon-005', topic: 'bonding', skill: 'bonding/polarity', q: 'The bond in NaCl is best described as…', opts: ['nonpolar covalent', 'polar covalent', 'ionic, from the large ΔEN', 'metallic'], a: 2, why: 'This is asking what kind of bond joins sodium and chlorine. When the electronegativity difference is large, one atom takes the electron instead of sharing it. Sodium and chlorine differ by about 2.2 on the Pauling scale, well past the ionic mark. Sodium hands its electron over, giving a lattice of Na⁺ and Cl⁻.' },
  { id: 'bon-036', tier: 1, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'How many covalent bonds does nitrogen usually form?', opts: ['3', '2', '4', '5'], a: 0, why: 'This is asking how many bonds a nitrogen atom normally makes. An atom shares electrons until its outer shell holds eight, and each shared pair counts as one bond. Nitrogen brings 5 valence electrons, so it needs 8 − 5 = 3 more and forms 3 bonds.' },
  { id: 'bon-037', tier: 1, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Boron in BF₃ has three bonding groups and no lone pairs. The shape and bond angle are…', opts: ['tetrahedral, 109.5°', 'trigonal pyramidal, 107°', 'bent, 104.5°', 'trigonal planar, 120°'], a: 3, why: 'This is asking you to turn a group count into a shape. Groups of electrons around a central atom spread as far apart as they can get, and three groups do that in a flat triangle. Sharing 360° between three directions leaves 120° between neighbours, so BF₃ is trigonal planar.' },
  { id: 'bon-038', tier: 1, topic: 'bonding', skill: 'bonding/bond-properties', q: 'A triple bond consists of…', opts: ['3 sigma (σ) bonds', '2 sigma (σ) + 1 pi (π)', '1 sigma (σ) + 2 pi (π)', '3 pi (π) bonds'], a: 2, why: 'This is asking what the three bonds of a triple bond are made of. The first bond between two atoms is always a sigma bond, from orbitals meeting head-on along the line between the nuclei. Every extra bond is a pi bond, from p orbitals overlapping sideways, so a triple bond is one sigma and two pi.' },
  { id: 'bon-039', tier: 1, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Nitrogen in NH₃ carries three bonds and one lone pair. The shape of the molecule is…', opts: ['tetrahedral', 'trigonal pyramidal', 'trigonal planar', 'bent'], a: 1, why: 'This is asking for the shape you would see, not the arrangement of the groups. All four groups repel each other into a tetrahedral arrangement, but a lone pair is invisible in the drawn shape. Three bonds under one lone pair leaves a squashed pyramid, with angles of about 107° rather than 109.5°.', misconception: 'The lone pair is counted for the arrangement and then not drawn, and skipping the first half is what produces "trigonal planar". Count every group — bonds and lone pairs together — to place them, then name the shape from the atoms alone. Four groups with one lone pair is trigonal pyramidal; four groups with two lone pairs is bent, which is water.' },
  { id: 'bon-040', tier: 1, topic: 'bonding', skill: 'bonding/bond-properties', q: 'How many sigma and pi bonds are in ethene, H₂C=CH₂?', opts: ['4 sigma (σ) and 2 pi (π)', '5 sigma (σ) and 1 pi (π)', '6 sigma (σ) and 0 pi (π)', '5 sigma (σ) and 2 pi (π)'], a: 1, why: 'This is asking you to sort the bonds of a real molecule into the two kinds. Every first bond between a pair of atoms is a sigma bond, and only the extra bonds of a double or triple bond are pi. Four C–H bonds plus the first half of the C=C gives 5 sigma, and the second half of the C=C is the single pi.', misconception: 'A double bond is one sigma plus one pi, not two pi. Counting it as two pi bonds drops a sigma from the total and gives 4 sigma and 2 pi. The rule never changes: the first bond of any pair is sigma, and pi bonds only ever come second and third.' },
  // ---- 11-20 Core ----
  { id: 'bon-041', tier: 2, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'How many valence electrons must a Lewis structure of ammonia, NH₃, account for?', opts: ['10', '6', '8', '14'], a: 2, why: 'This is asking for the electron budget before any bonds are drawn. A Lewis structure shows every valence electron, so add up what each atom brings: nitrogen brings 5 and each hydrogen brings 1. That is 5 + 3 = 8 electrons, which the finished structure shows as three bonding pairs and one lone pair.', misconception: 'The belief to drop is that every atom in the structure needs eight electrons of its own. Hydrogen is full with two, so only the central nitrogen reaches eight, and it does so by counting each shared pair as its own. Count what the atoms bring, then hand the electrons out.' },
  { id: 'bon-042', tier: 2, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'The oxygen in a water molecule carries two bonds and two lone pairs. What is the shape and the bond angle?', opts: ['tetrahedral, 109.5°', 'trigonal pyramidal, 107°', 'linear, 180°', 'bent, about 104.5°'], a: 3, why: 'This is asking for the shape you would see, which counts only the atoms. All four groups — two bonds and two lone pairs — repel one another into a tetrahedral arrangement, but a lone pair is invisible in the drawn shape. Two bonds left under two lone pairs give a bent molecule, and because a lone pair pushes harder than a bonding pair the angle closes from 109.5° to about 104.5°.', misconception: 'The belief to drop is that a molecule with two bonds must be linear. Two bonds are linear only when nothing else sits on the central atom, as in CO₂. Count the lone pairs into the arrangement first, then name the shape from the atoms alone.' },
  { id: 'bon-010', tier: 2, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Which of these molecules has the LARGEST bond angle?', opts: ['BF₃', 'NH₃', 'CH₄', 'H₂O'], a: 0, why: 'This is asking you to order four shapes by their angles. Fewer groups on the central atom means the groups can spread further apart, and a lone pair pushes harder than a bonding pair and squeezes the rest closed. BF₃ has three groups at 120°, methane four at 109.5°, ammonia loses a little to one lone pair at 107° and water loses more to two at 104.5°.', misconception: 'The belief to drop is that the largest molecule has the largest angle. The angle comes from how many groups sit on the central atom and how many of those are lone pairs, not from the size of the atoms attached. Three groups always beat four, whatever is on the ends.' },
  { id: 'bon-011', tier: 2, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'What is the formal charge on the nitrogen atom in the nitrate ion, NO₃⁻?', opts: ['−1', '0', '+2', '+1'], a: 3, why: 'This is asking for a bookkeeping number rather than a measured charge. Formal charge is valence electrons − lone-pair electrons − ½(bonding electrons). Nitrogen in NO₃⁻ brings 5 valence electrons, holds no lone pair and shares eight bonding electrons, so it is 5 − 0 − ½(8) = +1.', misconception: 'The belief to drop is that the charge written on the ion belongs to the central atom. The ion is −1 overall, but that is shared out: nitrogen comes to +1 and the two singly bonded oxygens to −1 each, which sums to −1. Work out each atom\'s own formal charge instead of reading the label.' },
  { id: 'bon-043', tier: 2, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'In the cyanide ion, drawn as C≡N with one lone pair on each atom, what is the formal charge on the carbon?', opts: ['−1', '0', '+1', '−2'], a: 0, why: 'This is asking you to apply the formal charge count to one atom. Formal charge is valence electrons − lone-pair electrons − ½(bonding electrons). Carbon brings 4, holds one lone pair worth 2, and shares the six bonding electrons of the triple bond, so it is 4 − 2 − 3 = −1.', misconception: 'The belief to drop is that the ion\'s −1 charge must be split between its two atoms. Formal charge is worked out atom by atom, and here nitrogen comes to 5 − 2 − 3 = 0 while carbon takes the whole −1. That is why cyanide attacks other molecules through its carbon.' },
  { id: 'bon-044', tier: 2, topic: 'bonding', skill: 'bonding/bond-properties', q: 'How many sigma (σ) and pi (π) bonds are there in hydrogen cyanide, H–C≡N?', opts: ['3 sigma and 1 pi', '2 sigma and 2 pi', '4 sigma and 0 pi', '2 sigma and 3 pi'], a: 1, why: 'This is asking you to sort the bonds of a molecule into the two kinds. The first bond between any pair of atoms is a sigma bond, formed head-on, and every extra bond in that pair is a pi bond, formed sideways. The H–C bond is one sigma, and the C≡N triple bond is one sigma plus two pi, giving 2 sigma and 2 pi in all.', misconception: 'The belief to drop is that a triple bond is three of the same thing. Only the first of the three is a sigma bond; the other two are pi bonds lying at right angles to each other. The rule never changes: one sigma per bonded pair, and pi bonds only ever come second and third.' },
  { id: 'bon-013', tier: 2, topic: 'bonding', skill: 'bonding/polarity', q: 'Which molecule has polar bonds but no overall dipole?', opts: ['CHCl₃', 'CCl₄', 'NH₃', 'SO₂'], a: 1, why: 'This is asking you to add the bond dipoles as arrows rather than count them. Each polar bond acts like an arrow pointing towards the more electronegative atom, and a molecule is polar only when those arrows fail to cancel. CCl₄ has four identical C–Cl arrows pointing to the corners of a tetrahedron, and they cancel exactly, so the molecule is nonpolar.', misconception: 'The belief to drop is that polar bonds make a polar molecule. Shape decides: CO₂, BF₃ and CCl₄ all contain genuinely polar bonds and are nonpolar overall, because their symmetry sets the arrows against one another. The question to ask is never "are the bonds polar" but "can the arrows cancel".' },
  { id: 'bon-016', tier: 2, topic: 'bonding', skill: 'bonding/polarity', q: 'Which isomer of 1,2-dichloroethene has a dipole moment — the one with both chlorines on the same side (cis) or the one with them on opposite sides (trans)?', opts: ['both', 'trans only', 'cis only', 'neither'], a: 2, why: 'This is asking you to compare two molecules that differ only in shape. The pi bond of a C=C locks the two ends against twisting, so the two arrangements are separate substances. In the trans form the two C–Cl arrows point opposite ways and cancel; in the cis form they lie on the same side and add, so only the cis isomer is polar.', misconception: 'The belief to drop is that two molecules sharing a formula must share their properties. A pi bond stops rotation, so cis and trans are fixed and genuinely different: they have different boiling points and only one of them is polar. A single C–C bond turns freely and has no such pair.' },
  { id: 'bon-045', tier: 2, topic: 'bonding', skill: 'states/imf', q: 'Water (18 g/mol) boils at 100 °C while hydrogen sulfide (34 g/mol) boils at −60 °C. Why does the lighter substance boil higher?', opts: ['water molecules are held together by covalent bonds and H₂S molecules are not', 'sulfur is the larger atom, so H₂S molecules slip past one another', 'water molecules hydrogen bond to each other and H₂S molecules cannot', 'water is a liquid at room temperature, so it must be the heavier substance'], a: 2, why: 'This is asking what boiling actually breaks. Boiling pulls whole molecules away from one another and leaves the bonds inside each molecule untouched, so a boiling point measures the attraction between molecules. Water has hydrogen attached to oxygen and lone pairs on that oxygen, so its molecules hydrogen bond to each other; sulfur does not pull hard enough for that, leaving H₂S with only the much weaker dispersion and dipole forces.', misconception: 'The belief to drop is that boiling breaks the bonds inside a molecule. Steam is still H₂O, with its O–H bonds intact, and only the attractions between neighbouring molecules have been broken. That is also why a heavier molecule need not boil higher: hydrogen bonding beats the extra mass here by 160 degrees.' },
  { id: 'bon-046', tier: 2, topic: 'bonding', skill: 'states/imf', q: 'F₂, Cl₂, Br₂ and I₂ are all nonpolar molecules. Which has the highest boiling point?', opts: ['F₂, the most electronegative', 'Cl₂, a gas at room temperature', 'they all boil at the same temperature', 'I₂, which has the most electrons'], a: 3, why: 'This is asking which attraction is left when a molecule has no dipole at all. Dispersion forces act between all molecules and come from the momentary uneven spread of their electrons, so they grow stronger the more electrons a molecule has. Down the halogens the boiling point climbs steadily: F₂ at −188 °C, Cl₂ at −34 °C, Br₂ at 59 °C and I₂ at 184 °C.', misconception: 'The belief to drop is that a nonpolar molecule has no forces between its molecules at all. If that were so, no nonpolar substance could ever be a liquid, yet iodine is a solid at room temperature. Dispersion is always present, and for a large molecule it outweighs the dipole forces of a small polar one.' },
  // ---- 21+ Contest ----
  { id: 'bon-006', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'What is the molecular shape of XeF₄?', opts: ['tetrahedral', 'seesaw', 'square pyramidal', 'square planar'], a: 3, why: '6 domains: 4 bonds + 2 lone pairs trans to each other → AX₄E₂ = <b>square planar</b>.', misconception: 'The <em>shape</em> of a molecule names where the atoms are; the <em>electron geometry</em> names where all the domains are, lone pairs included. XeF₄ has six domains, so its electron geometry is octahedral — but with the two lone pairs opposite each other, the four atoms describe a square plane. Answering "tetrahedral" or "square pyramidal" means either forgetting the lone pairs exist or forgetting that they are invisible in the shape.' },
  { id: 'bon-007', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Which molecule is paramagnetic?', opts: ['O₂', 'N₂', 'F₂', 'C₂'], a: 0, why: 'O₂ has two unpaired electrons, one in each of its two π* orbitals. Unpaired electrons make a molecule magnetic, and liquid oxygen really does stick to a magnet. A Lewis structure gives O₂ no unpaired electrons at all, which is why molecular orbital theory is needed here.' },
  { id: 'bon-008', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Bond order of the superoxide ion O₂⁻?', opts: ['1', '1.5', '2', '2.5'], a: 1, why: '13 valence e⁻ → extra electron in π* → BO = (8−5)/2 = 1.5. Order: O₂⁺ 2.5 > O₂ 2 > O₂⁻ 1.5 > O₂²⁻ 1.', misconception: 'Superoxide (O₂⁻) and peroxide (O₂²⁻) are different ions and only one extra electron separates them. One electron into π* costs half a bond (BO 1.5); two extra electrons cost a full bond (BO 1), which is the peroxide value. Answering 1 means counting the charge as though it were 2− — always read the charge before you fill the antibonding set.' },
  { id: 'bon-009', tier: 3, topic: 'bonding', skill: 'bonding/hybridisation', q: 'Hybridization of sulfur in SF₄?', opts: ['sp²', 'sp³', 'sp³d', 'sp³d²'], a: 2, why: '4 bonds + 1 lone pair = 5 domains → sp³d, seesaw shape.', misconception: 'Hybridisation counts electron <em>domains</em>, not bonds. SF₄ has four bonds plus one lone pair — five domains — so it is sp³d and seesaw, not the sp³ that counting bonds alone would suggest. Any lone pair on the central atom occupies a hybrid orbital and must be counted before the label is assigned.' },
  { id: 'bon-012', tier: 3, topic: 'bonding', skill: 'bonding/bond-properties', q: 'The N–O bond order in NO₃⁻ is…', opts: ['1', '1.5', '1.33', '2'], a: 2, why: 'One double bond delocalized over three equivalent positions: 4 bonds / 3 positions = 4/3.' },
  { id: 'bon-014', tier: 3, topic: 'bonding', skill: 'bonding/bond-properties', q: 'Shortest carbon–oxygen bond?', opts: ['C≡O in carbon monoxide', 'C=O in acetone', 'C–O in methanol', 'C–O in CO₃²⁻'], a: 0, why: 'CO has bond order 3 (isoelectronic with N₂) — higher order = shorter, stronger.' },
  { id: 'bon-015', tier: 3, topic: 'bonding', skill: 'bonding/hybridisation', q: 'Hybridization of the central iodine in I₃⁻?', opts: ['sp', 'sp³', 'sp³d²', 'sp³d'], a: 3, why: '2 bonds + 3 lone pairs = 5 domains (sp³d); lone pairs take the equator → linear ion.' },
  { id: 'bon-017', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Removing one electron from N₂ makes the bond…', opts: ['stronger', 'weaker', 'unchanged', 'ionic'], a: 1, why: 'The electron leaves a BONDING orbital: BO drops 3 → 2.5. (For O₂ the electron leaves π* antibonding, so O₂⁺ is STRONGER — compare the two cases!)', misconception: 'Whether ionisation strengthens or weakens a bond depends entirely on which orbital the electron leaves. Pull an electron out of a <em>bonding</em> orbital, as in N₂ → N₂⁺, and the bond order drops from 3 to 2.5 and the bond weakens. Pull one out of an <em>antibonding</em> orbital, as in O₂ → O₂⁺, and the bond order rises from 2 to 2.5 and the bond gets stronger. "Removing electrons always weakens bonds" is the model to discard.' , why2: 'Ask one question instead of two: <b>is the HOMO bonding or antibonding?</b> Ionisation always removes the highest-energy occupied electron, so the answer is entirely determined by what that orbital is. N₂ fills up to σ2p — bonding — so removing it costs half a bond. O₂ has two more electrons, which sit in π* — antibonding — so removing one <em>repairs</em> half a bond. The bond lengths confirm both: N₂ 110 pm lengthens to 112 pm in N₂⁺, while O₂ 121 pm contracts to 112 pm in O₂⁺. Same operation, opposite result, because the ledger entry being deleted has a different sign.' },
  { id: 'bon-018', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'The acetylide ion C₂²⁻ has bond order…', opts: ['3', '2', '2.5', '1'], a: 0, why: '10 valence electrons — isoelectronic with N₂ → triple bond. That\'s the C≡C in calcium carbide.' },
  { id: 'bon-019', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'MO theory predicts which species does NOT exist?', opts: ['H₂⁺', 'He₂²⁺', 'B₂', 'He₂'], a: 3, why: 'He₂: 2 bonding + 2 antibonding electrons → bond order 0. (H₂⁺ and He₂²⁺ both have BO ½ — weakly bound but real.)' },
  { id: 'bon-020', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Shape of ClF₃?', opts: ['trigonal planar', 'trigonal pyramidal', 'bent', 'T-shaped'], a: 3, why: '5 domains, 2 lone pairs in equatorial spots → the three bonds form a T. AX₃E₂.' },
  { id: 'bon-021', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Which cannot have an expanded octet?', opts: ['N', 'S', 'P', 'Xe'], a: 0, why: 'Period 2 has no d orbitals available — N maxes at 4 bonds (NH₄⁺). PCl₅, SF₆, XeF₄ are all fine.', misconception: 'The "expanded octet" is only available to period 3 and beyond. Nitrogen, oxygen, carbon and fluorine have no accessible d orbitals and cannot exceed eight electrons under any circumstances — so a Lewis structure with five bonds to N is wrong, however tidy it looks. Phosphorus, sulfur and xenon can (PCl₅, SF₆, XeF₄), which is why P and N behave so differently despite sharing a group.' },
  { id: 'bon-022', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'B₂ is paramagnetic. This is evidence that…', opts: ['σ2p lies below π2p', 'π2p lies below σ2p', 'B₂ has a triple bond', 's–p mixing is absent'], a: 1, why: 'With π2p lower, B₂\'s two 2p electrons go one each into the two degenerate π orbitals (Hund) → 2 unpaired. If σ2p were lower they\'d pair up — diamagnetic. Experiment decides!', misconception: 'The "σ2p below π2p" MO ordering is <em>not</em> universal — treat it as the exception, not the rule. It applies to B₂, C₂ and N₂ specifically, because their 2s and 2p orbitals sit close enough in energy for s–p mixing to push σ2p above the π2p pair. From O₂ onward the 2s–2p gap is wider, mixing is weak, and the order flips back to the naively-expected σ2p below π2p. Always check which side of that N₂/O₂ line a diatomic is on before drawing its MO diagram from memory.' },
  { id: 'bon-023', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Bond angle comparison: NO₂⁺ vs NO₂⁻?', opts: ['NO₂⁺ smaller', 'equal', 'NO₂⁺ is linear (180°), NO₂⁻ is bent (~115°)', 'both linear'], a: 2, why: 'NO₂⁺ has 2 domains, no lone pair → linear. NO₂⁻ has a full lone pair squeezing the bond angle below 120°.', misconception: 'Charge changes the DOMAIN COUNT, so neither ion can be read off the neutral NO₂ skeleton. NO₂⁺ has two domains and no lone pair (linear, 180°), while NO₂⁻ carries a full lone pair that squeezes its angle below 120°. Expecting the cation to have the smaller angle treats positive charge as a general contraction of the geometry rather than as the removal of a lone pair.' },
  { id: 'bon-024', tier: 3, topic: 'bonding', skill: 'bonding/hybridisation', q: 'Which C–H bond is most acidic?', opts: ['sp³ (ethane)', 'sp² (ethylene)', 'all equal', 'sp (acetylene)'], a: 3, why: 'More s-character holds the anion\'s lone pair closer to the nucleus: sp (50% s, pKa 25) ≫ sp² (44) ≫ sp³ (50).', misconception: 'C–H acidity is not about how strongly carbon holds hydrogen; it is about how well the resulting <em>carbanion</em> is stabilised. More s-character in the hybrid holds the lone pair closer to the nucleus, so acidity runs sp (pKa ≈ 25) ≫ sp² (≈ 44) ≫ sp³ (≈ 50) — a 25-order-of-magnitude spread across identical-looking C–H bonds. Judging acidity by looking at the acid rather than its conjugate base is the general form of this mistake.' },
  { id: 'bon-025', tier: 3, topic: 'bonding', skill: 'bonding/bond-properties', q: 'The C–C bond length order is…', opts: ['C≡C < C=C < C–C', 'C–C < C=C < C≡C', 'C=C < C–C < C≡C', 'all equal'], a: 0, why: 'More shared pairs pull nuclei closer: 120 pm (≡) < 134 (=) < 154 (–). Strength runs the opposite way.', misconception: 'Bond length and bond strength run in <em>opposite</em> directions, and reading one off the other as if they tracked together is the trap. More shared pairs pull the nuclei closer: C≡C (120 pm) &lt; C=C (134) &lt; C–C (154), while the strengths run the other way, 837 &gt; 614 &gt; 348 kJ/mol. Shorter always means stronger for the same pair of atoms.' },
  { id: 'bon-026', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Gas-phase C₂ is diamagnetic with a bond order of 2, yet its double bond is not the familiar σ + π pair. What is it, and why?', opts: ['Two π bonds and no net σ bond, because s–p mixing lifts σ2p above the degenerate π2p pair', 'One σ and one π bond, exactly as in ethene, because every double bond is one σ plus one π', 'One σ and two π bonds with one π orbital left empty, because carbon prefers a triple-bond framework', 'Two σ bonds built from sp hybrids, because head-on overlap is always the lower-energy option'], a: 0, why: 'Fill the diagram before naming the bond. C₂ has 8 valence electrons: σ2s² σ*2s² leaves a net of zero, and the remaining four go into the π2p pair — which in B₂, C₂ and N₂ lies <b>below</b> σ2p because s–p mixing pushes σ2p up. Bond order = (6 − 2)/2 = 2, and both bonding pairs are π. The diamagnetism is the check: a half-filled π set (as in B₂) would leave two unpaired electrons by Hund\'s rule, so a diamagnetic C₂ means the π level is full and σ2p is empty. The short 124 pm bond is a double bond made of two sideways overlaps.', misconception: 'σ-then-π is a valence-bond <em>template</em>, not a law of counting. It holds for ethene because the σ framework is filled first there, but a molecular orbital diagram allocates electrons by orbital energy, and in the first half of period 2 the π2p orbitals are the lower ones. Deciding what a bond is made of before filling the diagram is what turns C₂ into a phantom ethene; the honest order is fill, count, then describe.' },
  { id: 'bon-027', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Dinitrogen monoxide is linear with the connectivity N–N–O (N–N 113 pm, N–O 119 pm). Which resonance structure is the leading contributor?', opts: ['N≡N⁺–O⁻, a triple N–N and a single N–O, with the negative formal charge on oxygen', 'N⁻=N⁺=O, two double bonds, with the negative formal charge on the terminal nitrogen', 'The structure carrying no formal charge at all, reached by giving the central nitrogen five bonds', 'N⁻–N⁺≡O, a single N–N and a triple N–O, placing a 2− formal charge on the terminal nitrogen'], a: 0, why: 'Two rules, applied in order. First, legality: nitrogen is a period-2 atom with no accessible d orbitals, so the zero-formal-charge structure would need ten electrons on the central N and simply does not exist — "minimise formal charge" has nothing to select here. Second, among the legal structures, prefer the one that puts negative formal charge on the more electronegative atom. Both N≡N⁺–O⁻ (0, +1, −1) and N⁻=N⁺=O (−1, +1, 0) are reasonable; the first wins because the −1 sits on oxygen, and the 2− structure loses on charge separation. The measured N–N of 113 pm, close to N₂\'s own 110 pm, is the evidence: real N₂O has substantial triple-bond character in the N–N linkage.', misconception: '"The best Lewis structure has zero formal charges" is a shortcut, not the rule, and it is only usable when a legal zero-charge structure exists. The actual rule is: satisfy the octet for period-2 atoms first, then minimise the <em>magnitude</em> of formal charges, then place any remaining negative charge on the most electronegative atom. Applying the shortcut first is what produces five-bonded nitrogen — a structure no amount of tidy arithmetic can make real.' },
  { id: 'bon-028', tier: 3, topic: 'bonding', skill: 'bonding/polarity', q: 'NH₃ has a dipole moment of 1.47 D, but NF₃ — built from far more polar bonds — measures only 0.24 D. Both are trigonal pyramidal. The reason is…', opts: ['The N–F bond dipoles point away from nitrogen and oppose the lone-pair moment, whereas in NH₃ the bond and lone-pair moments point the same way', 'NF₃ is much closer to planar than NH₃, so its three bond dipoles very nearly cancel by symmetry', 'The N–F bonds are so polar that they are effectively ionic, and an ionic bond contributes no dipole moment', 'Fluorine lone pairs donate π density back to nitrogen, cancelling the σ polarity of each N–F bond'], a: 0, why: 'A molecular dipole is a vector sum over the whole charge distribution, and the lone pair is one of the vectors. In NH₃ the bond moments run H → N (nitrogen is the negative end) and the lone pair sticks out on the same side of the nitrogen, so the two contributions <b>add</b> to 1.47 D. In NF₃ the bond moments run N → F, pointing down towards the fluorines, directly against the lone pair — they largely cancel, leaving 0.24 D. Geometry cannot be the explanation: NF₃ is <em>more</em> pyramidal than ammonia, with a bond angle of 102° against 107°, so a flattening argument predicts exactly the wrong sign.', misconception: 'The model to discard is "molecular dipole = sum of bond dipoles". A lone pair is a lobe of charge sitting off-centre, and it carries a moment as real as any bond does — often the largest single contribution. Once it is in the sum, the NH₃/NF₃ pair stops being paradoxical: the same lone pair reinforces the bond moments in one molecule and opposes them in the other. Reaching for a symmetry or flattening explanation is the reflex to catch, because the bond angles rule it out before the argument starts.' },
  { id: 'bon-029', tier: 3, topic: 'bonding', skill: ['bonding/polarity', 'bonding/mo-theory'], q: 'Carbon monoxide has a dipole moment of only 0.11 D, and its negative end is the CARBON, though oxygen is far more electronegative. The best account is…', opts: ['The dative character of the triple bond gives formal charges C⁻ and O⁺, and the HOMO is a lone pair sitting mainly on carbon; together these outweigh the σ polarisation towards oxygen', 'The molecule is linear, so its bond dipoles cancel and only a small residual moment survives', 'Carbon is genuinely more electronegative than oxygen here, because the high s character of an sp hybrid raises effective electronegativity', 'The C≡O bond is the strongest known covalent bond, and a very strong bond necessarily shares its electrons evenly'], a: 0, why: 'Count the bonds, then look at where the electrons actually are. Building :C≡O: from neutral atoms needs one of the three pairs to come from oxygen alone, giving formal charges of −1 on carbon and +1 on oxygen; that charge transfer pushes density onto carbon and runs against the σ polarisation that electronegativity produces. The two nearly cancel, which is why the moment is a feeble 0.11 D, and the π back-transfer plus the carbon-based σ HOMO tip the balance so the residue points C⁻→O⁺. The chemistry confirms it: CO binds metals and haem iron through its <b>carbon</b>, the end with the available lone pair.', misconception: 'The cancellation argument is imported from CO₂ and cannot apply here: cancellation needs two or more bond moments related by symmetry, and a heteronuclear diatomic has exactly one bond and no symmetry to cancel it. Behind that lies the wider error of reading dipole direction straight off an electronegativity table. Electronegativity governs how a shared pair is polarised, but a dative pair moves a whole electron\'s worth of density the other way, and in CO those two effects nearly annihilate each other.' },
  { id: 'bon-030', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'N(CH₃)₃ is pyramidal at nitrogen, but N(SiH₃)₃ is planar, and its N–Si bonds are shorter than the sum of the covalent radii. What does this establish?', opts: ['The nitrogen lone pair is delocalised into acceptor orbitals on silicon, which pays for flattening the nitrogen and shortens the N–Si bonds', 'Nothing about bonding: the SiH₃ groups are bulky, and steric repulsion alone forces the molecule open to planar', 'Nitrogen inverts rapidly, so the pyramid is real and only the time-averaged structure looks planar', 'Silicon is more electronegative than carbon, so induction pulls the lone pair away and removes a domain'], a: 0, why: 'VSEPR gives a first guess, and the two pieces of evidence together say the guess fails. If nitrogen simply kept its lone pair, four domains would make it pyramidal like the amine — but a lone pair delocalised onto the silicons is no longer a stereochemically active domain, and the geometry flattens to trigonal planar. The bond lengths are the second, independent line of evidence: a delocalised pair adds π character, so the N–Si bonds come out <b>shorter</b> than a single bond should be, which neither sterics nor induction predicts. Silicon is also less electronegative than carbon, not more, so the induction story has the trend backwards.', misconception: 'Sterics is the reflex explanation and here it is the wrong one — the giveaway is the bond <em>shortening</em>. Steric strain pushes atoms apart; it can flatten a centre, but it never pulls the bonds in below a normal single-bond length. When a geometry change and a bond contraction appear together, the cause is electronic: something is delocalising and adding bond order. The averaging answer fails on the same evidence, since a rapidly inverting pyramid still has ordinary long single bonds.' },
  { id: 'bon-031', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'At low temperature the ¹⁹F NMR of SF₄ shows two signals of equal intensity, and the S–F bonds fall into two sets, 165 pm and 155 pm. Which arrangement fits both observations?', opts: ['A seesaw: five domains with the lone pair equatorial, giving two long axial and two short equatorial fluorines', 'A trigonal bipyramid with the lone pair axial, giving one axial fluorine and three equatorial ones', 'A tetrahedron about sulfur with the lone pair delocalised over the cage, so all four fluorines are equivalent', 'A square plane of fluorines with the lone pair above it, so all four fluorines are equivalent'], a: 0, why: 'Two signals of equal intensity means two environments holding two fluorines each — that single fact eliminates three of the four. Sulfur brings six valence electrons and four bonds, so there are five domains; the lone pair takes an <b>equatorial</b> site, where it has only two neighbours at 90°, rather than an axial one with three. That leaves two axial and two equatorial fluorines: the 2:2 pattern the spectrum shows. The bond lengths agree, since the two axial bonds lean away from the fat equatorial lone pair and stretch to 165 pm against 155 pm for the equatorial pair. Warm the sample and Berry pseudorotation averages the sites into one signal, which is why the low temperature was specified.', misconception: 'Putting the lone pair axial is the error, and it predicts a 3:1 spectrum that is never seen. The rule is not arbitrary: in a trigonal bipyramid an axial site has three neighbours at 90°, an equatorial site only two, so the domain that repels hardest — always the lone pair, which is held by one nucleus rather than shared between two — takes the roomier equatorial position. The same rule places both lone pairs of ClF₃ equatorially and makes it T-shaped, and all three of I₃⁻\'s, making it linear.' },
  { id: 'bon-032', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'N₂ and CO are isoelectronic, both of bond order 3, and the C≡O bond (1072 kJ/mol) is the stronger of the two — yet CO binds metal centres readily and N₂ barely at all. Why?', opts: ['CO\'s HOMO is a high-lying lone pair concentrated on carbon and its π* orbitals are low enough to accept back-donation; N₂\'s HOMO lies lower and is shared between two identical atoms', 'CO is polar and N₂ is not, so it is the electrostatic pull of the CO dipole that holds the ligand on the metal', 'One of CO\'s three bonds is dative, so its real bond order is 2, and the weaker bond makes the molecule reactive', 'N₂ holds the strongest bond known at 945 kJ/mol, so it has no electrons to spare for a metal centre'], a: 0, why: 'Bond strength is the wrong axis: it says what it costs to pull the molecule apart, and coordination does not pull the molecule apart. What matters is the frontier orbitals. Isoelectronic species need not have their electrons in the same <em>places</em> — CO is heteronuclear, so its σ HOMO is lopsided onto the carbon and lies high in energy, a lone pair pointed straight at an empty metal orbital, while its π* orbitals sit low enough to take density back from the filled metal d set. That synergic donation and back-donation is what a strong M–CO bond is made of. N₂\'s orbitals are symmetric and lower-lying, so it is both the poorer donor and the poorer acceptor, and N₂ complexes are correspondingly rare and fragile.', misconception: 'Ligand strength is not read off a dipole moment. CO\'s moment is a mere 0.11 D — one of the smallest of any heteronuclear molecule — so an electrostatic account predicts almost no binding at all, and it also gets the direction wrong, since the moment is far too weak to explain why CO always coordinates through carbon. What actually points CO at the metal is the shape and energy of one orbital: the carbon-heavy σ HOMO. Isoelectronic means the same electron count, never the same orbital energies or the same chemistry.' },
  { id: 'bon-033', tier: 3, topic: 'bonding', skill: ['bonding/lewis-vsepr', 'bonding/bond-properties'], q: 'In N,N-dimethylformamide the two N-methyl groups give two separate ¹H NMR singlets at 25 °C which coalesce on heating, and the C–N bond is 133 pm against 147 pm in an amine. What does this establish?', opts: ['The nitrogen lone pair is delocalised into the C=O π*, giving the C–N bond partial double character and a rotation barrier near 80 kJ/mol', 'Inversion at the pyramidal nitrogen is slow on the NMR timescale, so the two methyl groups are frozen into different environments', 'One methyl group hydrogen bonds to the carbonyl oxygen and the other does not, which shifts the two signals apart', 'Rotation about the C=O double bond is restricted, holding the molecule in a single conformation'], a: 0, why: 'The two observations are the same fact seen twice. Delocalising the nitrogen lone pair into the carbonyl π* gives the resonance form with a C=N⁺ and an O⁻, so the C–N linkage carries partial double-bond character — which shortens it to 133 pm (an amine\'s is 147) and, more tellingly, raises a barrier to twisting it. At 25 °C that barrier of roughly 80–90 kJ/mol is high enough to freeze rotation on the NMR timescale, so one methyl is permanently <em>cis</em> to the oxygen and the other <em>trans</em>: two singlets. Heat the sample and rotation outruns the timescale, and the two signals coalesce into one. The C=O also lengthens to about 124 pm from a ketone\'s 120 pm, exactly as the shared π density demands.', misconception: 'Nitrogen inversion is the wrong process on two counts. First, an amide nitrogen is planar precisely <em>because</em> its lone pair is delocalised, so there is no pyramid to invert. Second, even in a genuine amine, inversion has a barrier of only about 25 kJ/mol and is far too fast to be frozen out at room temperature. The process being slowed here is <b>rotation</b> about a bond with partial double character — and the fact that it can be slowed at all is the experimental proof that the delocalisation is real.' },
  { id: 'bon-034', tier: 3, topic: 'bonding', skill: ['bonding/hybridisation', 'bonding/bond-properties'], q: 'The central C–C bond of buta-1,3-diene is 147 pm, well short of ethane\'s 154 pm. In propyne, where no conjugation across that bond is possible, the CH₃–C bond is 146 pm. What follows?', opts: ['Most of the shortening comes from the higher s character of the hybrid orbitals joined, with π delocalisation contributing a smaller extra amount', 'Delocalisation equalises the two C–C linkages in butadiene at about 1.5 bonds each, as it does in benzene', 'Bond length is fixed by bond order alone, so butadiene\'s central bond must have an order of about 1.2', 'The propyne figure is irrelevant, since it is the length of a triple bond and not of the single bond next to it'], a: 0, why: 'The propyne number is a control experiment, and it is what makes this an argument rather than a story. Propyne\'s CH₃–C bond joins an sp³ carbon to an sp carbon and measures 146 pm — as short as butadiene\'s central bond — yet no conjugation can cross it. So the bulk of the contraction must come from the property both cases share: hybrids with more s character are more compact, and both butadiene\'s central carbons (sp²) and propyne\'s alkyne carbon (sp) exceed ethane\'s sp³. Conjugation is real but second-order here, and butadiene\'s own numbers show it: the C1=C2 bond is 134 pm, essentially ethene\'s 134, so the π system has not redistributed itself much at all.', misconception: 'Benzene is the wrong model to carry into every conjugated system. Its equal 140 pm bonds come from its <em>symmetry</em> — a ring of six equivalent carbons whose two Kekulé structures are related by a rotation — and no open chain has that. Butadiene keeps a clear alternation, 134 and 147 pm, so it is a diene with a slightly shortened link between the double bonds, not a chain of one-and-a-half bonds. When an unexpectedly short bond appears, check hybridisation before invoking delocalisation: it is the larger effect more often than students expect.' },
  { id: 'bon-035', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Cyclopenta-1,3-diene has a pKa of about 16, on a par with water, while cyclohepta-1,3,5-triene comes in near 36 — despite the larger ring offering more π system to spread the charge. What does this show?', opts: ['Deprotonation makes the cyclopentadienyl anion aromatic, six π electrons over five equivalent carbons, while the seven-membered anion would hold eight π electrons and is antiaromatic', 'The seven-membered ring is the aromatic one — tropylium — so cycloheptatriene is really the stronger acid and the two pKa values have been quoted the wrong way round', 'Charge on the smaller ring simply sits closer to more nuclei, so a compact carbanion is always the better stabilised of the two', 'The extra sp³ CH₂ groups of the larger ring push electron density inductively onto its carbanion and destabilise it'], a: 0, why: 'Acidity is a statement about the conjugate base, so build both anions. Removing the sp³ proton from cyclopentadiene leaves a carbanion whose lone pair joins the two π bonds in a planar, fully conjugated ring: six π electrons over five carbons, a Hückel 4n+2 count, and the ring becomes aromatic with all five C–C bonds at 140 pm. Removing the corresponding proton from cycloheptatriene gives a planar conjugated ring with <b>eight</b> π electrons — a 4n count, which is destabilising, not stabilising. Twenty orders of magnitude in acidity separate them, and the extra delocalisation belongs to the ring that ionises worse: delocalisation is not automatically a stabiliser.', misconception: 'The aromatic seven-membered species is the tropylium <em>cation</em>, C₇H₇⁺, which is why cycloheptatriene loses a hydride so readily; its anion is a different species with two more electrons and the opposite Hückel count. Behind the mix-up sits a broader habit: judging stabilisation by how far the charge can spread, or by counting resonance structures. Both anions delocalise across their whole ring, so that measure cannot tell them apart — only the π electron count against 4n + 2 can, and it is worth checking the sign of the charge before deciding which ion the rule is being applied to.' },
];

export const STOICH_QUIZ: QuizQ[] = [
  // ---- 1-10 Basics ----
  { id: 'sto-001', topic: 'stoich', skill: 'stoich/mole-concept', q: 'What is the molar mass of water?', opts: ['16 g/mol', '18 g/mol', '20 g/mol', '10 g/mol'], a: 1, why: 'This is asking for the mass of one mole of water. Molar mass is the mass in grams of one mole, found by adding the atomic masses in the formula. H₂O is 2(1.01) + 16.00 = 18.02 g/mol, which rounds to 18 g/mol.' },
  { id: 'sto-002', topic: 'stoich', skill: 'stoich/mole-concept', q: 'One mole contains how many particles?', opts: ['6.022×10²³', '6.022×10²²', '3.011×10²³', '1.66×10⁻²⁴'], a: 0, why: 'This is asking how many particles make up one mole. A mole is a fixed count, the way a dozen is 12. That count is Avogadro\'s number, 6.022 × 10²³ particles per mole.' },
  { id: 'sto-003', topic: 'stoich', skill: 'stoich/mole-concept', q: 'How many moles are in 44 g of CO₂?', opts: ['0.5', '44', '2', '1'], a: 3, why: 'This is asking you to turn a mass into a number of moles. Divide the mass in grams by the molar mass, the mass of one mole. CO₂ is 12.0 + 2(16.0) = 44.0 g/mol, so 44 ÷ 44.0 = 1.00 mol.' },
  { id: 'sto-004', topic: 'stoich', skill: 'stoich/mole-concept', q: 'Which set of coefficients balances __H₂ + __O₂ → __H₂O?', opts: ['1, 1, 1', '2, 2, 1', '2, 1, 2', '1, 2, 2'], a: 2, why: 'This is asking for coefficients that give equal atom counts on both sides. A balanced equation has the same number of each atom left and right, because atoms are never created or destroyed. Try 2H₂ + O₂ → 2H₂O: that is 4 H and 2 O on each side.' },
  { id: 'sto-005', topic: 'stoich', skill: 'stoich/solution-conc', q: 'What is the molarity of a solution made by dissolving 1 mol of NaCl to a total volume of 2 L?', opts: ['2 M', '0.5 M', '1 M', '0.25 M'], a: 1, why: 'This is asking for the concentration of the solution. Molarity is moles of solute, the dissolved substance, divided by litres of solution. Here 1 mol in 2 L gives 1 ÷ 2 = 0.5 mol/L, written 0.5 M.' },
  { id: 'sto-026', tier: 1, topic: 'stoich', skill: 'stoich/mole-concept', q: 'How many molecules are in 2.0 mol of CO₂?', opts: ['3.0×10²³', '6.0×10²³', '1.2×10²⁴', '1.2×10²³'], a: 2, why: 'This is asking you to turn an amount in moles into a number of molecules. One mole is a fixed count of 6.022 × 10²³ particles, the way a dozen is 12, so multiply the moles by that count. Here 2.0 × 6.022 × 10²³ = 1.2 × 10²⁴ molecules.' },
  { id: 'sto-027', tier: 1, topic: 'stoich', skill: 'stoich/limiting-reagent', q: '3.0 mol of H₂ is mixed with 2.0 mol of O₂ for 2H₂ + O₂ → 2H₂O. Which statement is correct?', opts: ['O₂ runs out first, leaving H₂ over', 'H₂ runs out first, leaving O₂ over', 'both run out at the same moment', 'the masses are needed to decide this'], a: 1, why: 'This is asking which reactant limits the reaction. Divide each amount by its own coefficient in the balanced equation, and the smaller answer belongs to the reactant that runs out first. H₂ gives 3.0 ÷ 2 = 1.5 and O₂ gives 2.0 ÷ 1 = 2.0, so hydrogen runs out first.', misconception: 'Comparing the raw mole numbers is what makes O₂ look limiting, because 2.0 is less than 3.0. The coefficients decide the answer, not the size of the numbers: this reaction eats hydrogen twice as fast as oxygen, so the smaller pile of oxygen still outlasts it. Always divide by the coefficient before comparing.' },
  { id: 'sto-028', tier: 1, topic: 'stoich', skill: 'stoich/solution-conc', q: 'What mass of NaCl (58.5 g/mol) is needed to make 500 mL of 0.200 M solution?', opts: ['5.85 g', '11.7 g', '2.93 g', '58.5 g'], a: 0, why: 'This is asking you to go from a concentration to a mass. Molarity is moles per litre of solution, so moles = molarity × volume in litres, and mass = moles × molar mass. Here 0.200 × 0.500 = 0.100 mol, and 0.100 × 58.5 = 5.85 g.', misconception: 'Molarity is per LITRE, so 500 mL has to become 0.500 L before it is used. Treating 0.200 M as "0.200 mol in the flask" ignores the volume completely and doubles the answer to 11.7 g. Convert the volume first, every time.' },
  { id: 'sto-029', tier: 1, topic: 'stoich', skill: 'stoich/mole-concept', q: 'Which statement about 2H₂ + O₂ → 2H₂O is correct?', opts: ['2 g of H₂ react with 1 g of O₂', '2 molecules of H₂ make 1 molecule of H₂O', 'the coefficients are a ratio of masses', '2 mol of H₂ react with 1 mol of O₂'], a: 3, why: 'This is asking what the numbers in front of a formula actually count. A balanced equation is a recipe in moles, so the coefficients give a ratio of amounts, never a ratio of masses. Two moles of H₂ react with one mole of O₂ to make two moles of H₂O.', misconception: 'Coefficients are moles, and moles of different substances do not weigh the same. Two grams of H₂ is one mole, while one gram of O₂ is only about 0.03 mol, so the mass reading of this equation is nowhere near balanced. Convert to moles before comparing anything.' },
  { id: 'sto-030', tier: 1, topic: 'stoich', skill: 'stoich/mole-concept', q: 'What is the molar mass of calcium carbonate, CaCO₃? (Ca 40.1, C 12.0, O 16.0)', opts: ['68.1 g/mol', '100.1 g/mol', '116.1 g/mol', '56.1 g/mol'], a: 1, why: 'This is asking for the mass of one mole of calcium carbonate. Molar mass is the sum of the atomic masses in the formula, with each one counted as many times as its subscript says. Here 40.1 + 12.0 + 3(16.0) = 100.1 g/mol.', misconception: 'The subscript 3 applies to the oxygen only, and it is the digit most often dropped. Adding one oxygen instead of three gives 68.1 g/mol and makes every later mole calculation wrong by a third. Read the formula atom by atom and write the count next to each symbol before adding.' },
  // ---- 11-20 Core ----
  { id: 'sto-006', tier: 2, topic: 'stoich', skill: 'stoich/limiting-reagent', q: '4 mol of H₂ reacts with 1 mol of O₂ (2H₂ + O₂ → 2H₂O). How much water forms?', opts: ['2 mol', '4 mol', '1 mol', '3 mol'], a: 0, why: 'This is asking how much product a mixture can make once one reactant runs out. Divide each amount by its own coefficient in the balanced equation, and the smaller answer belongs to the reactant that limits everything: H₂ gives 4 ÷ 2 = 2 and O₂ gives 1 ÷ 1 = 1, so the oxygen runs out first. One mole of O₂ makes 2 mol of water, and 2 mol of H₂ is left unused.', misconception: 'The belief to drop is that the amount of product follows whichever reactant there is most of. It predicts 4 mol of water from the 4 mol of hydrogen. What actually happens is that only 1 mol of O₂ is present, and each O₂ can supply the oxygen for just two water molecules, so the reaction stops at 2 mol with hydrogen left over.' },
  { id: 'sto-024', tier: 2, topic: 'stoich', skill: 'stoich/mole-concept', q: '0.5 mol of aluminium reacts completely: 2Al + 6HCl → 2AlCl₃ + 3H₂. How many moles of H₂ form?', opts: ['0.75', '0.5', '1.0', '1.5'], a: 0, why: 'This is asking you to cross from one substance to another using the balanced equation. The coefficients are the only bridge between two amounts, and here they give 3 mol of H₂ for every 2 mol of Al. So the hydrogen formed is 0.5 × 3 ÷ 2 = 0.75 mol.', misconception: 'The belief to drop is that every coefficient in the equation enters the sum. Only the two belonging to the substances the question names matter, so aluminium to hydrogen is 2 to 3 and the 6 in front of HCl plays no part. Write those two coefficients down as a fraction before multiplying.' },
  { id: 'sto-031', tier: 2, topic: 'stoich', skill: 'stoich/mole-concept', q: 'Iron(III) oxide is reduced by carbon monoxide: Fe₂O₃ + 3CO → 2Fe + 3CO₂. What mass of iron forms from 32.0 g of Fe₂O₃? (Fe₂O₃ 159.7 g/mol, Fe 55.85 g/mol)', opts: ['11.2 g', '44.7 g', '22.4 g', '32.0 g'], a: 2, why: 'This is asking you to turn a mass of one substance into a mass of another. Grams never convert to grams directly: divide by the molar mass to get moles, cross to the other substance with the coefficients, then multiply by its molar mass. Here 32.0 ÷ 159.7 = 0.200 mol of Fe₂O₃, which gives 2 × 0.200 = 0.401 mol of iron, and 0.401 × 55.85 = 22.4 g.', misconception: 'The belief to drop is that the coefficients can be applied to the masses. They count moles, not grams, so the 2 in front of Fe doubles an amount in moles and never a mass in grams. Halving the mass instead of doubling the moles gives 11.2 g, which is the same slip made the other way round.' },
  { id: 'sto-032', tier: 2, topic: 'stoich', skill: 'stoich/yield', q: 'A reaction is predicted to give 12.2 g of ammonia, and 10.5 g is collected and dried. What is the percent yield?', opts: ['116%', '1.7%', '22.7%', '86.1%'], a: 3, why: 'This is asking what fraction of the possible product was actually obtained. Percent yield is the mass collected divided by the mass the balanced equation predicts, multiplied by 100. Here 10.5 ÷ 12.2 × 100 = 86.1%.', misconception: 'The belief to drop is that the order of the two masses does not matter. Dividing the other way round gives 116%, and a dried product cannot exceed what the equation allows. The predicted mass is the most the reaction could possibly give, so it always goes on the bottom.' },
  { id: 'sto-015', tier: 2, topic: 'stoich', skill: 'stoich/percent-composition', q: 'What is the mass percent of nitrogen in ammonium nitrate, NH₄NO₃ (molar mass 80 g/mol)?', opts: ['35%', '17.5%', '28%', '52%'], a: 0, why: 'This is asking what fraction of the compound\'s mass is nitrogen. Add the mass of every nitrogen atom in one formula unit, then divide by the molar mass of the whole compound. NH₄NO₃ holds two nitrogens, so that is 2 × 14 = 28 out of 80, and 28 ÷ 80 × 100 = 35%.', misconception: 'The belief to drop is that the N written at the front of the formula is the only one. NH₄NO₃ has a nitrogen in the ammonium part and another in the nitrate part, and counting one of them gives 17.5%, exactly half the right answer. Read a formula atom by atom and write the count beside each symbol before adding.' },
  { id: 'sto-009', tier: 2, topic: 'stoich', skill: 'stoich/empirical-formula', q: 'A compound is 40.0% carbon, 6.7% hydrogen and 53.3% oxygen by mass. What is its empirical formula?', opts: ['CHO', 'CH₂O', 'C₂H₄O', 'CH₃O'], a: 1, why: 'This is asking for the simplest whole-number ratio of the atoms. Take a 100 g sample so each percentage becomes a mass in grams, then divide each mass by that element\'s molar mass to get moles. That gives 40.0 ÷ 12.0 = 3.33, 6.7 ÷ 1.01 = 6.6 and 53.3 ÷ 16.0 = 3.33, and dividing all three by the smallest leaves 1 : 2 : 1, so the formula is CH₂O.', misconception: 'The belief to drop is that the percentages themselves give the atom ratio. Percentages are masses, and one gram of hydrogen holds twelve times as many atoms as one gram of carbon. Turn every mass into moles before comparing anything.' },
  { id: 'sto-016', tier: 2, topic: 'stoich', skill: 'stoich/empirical-formula', q: 'A compound has the empirical formula CH₂ and a molar mass of 56 g/mol. What is its molecular formula?', opts: ['C₂H₄', 'C₄H₈', 'C₃H₆', 'C₅H₁₀'], a: 1, why: 'This is asking how many empirical units make up one molecule. The molecular formula is the empirical formula scaled by (molar mass ÷ empirical formula mass). One CH₂ unit weighs 12 + 2(1) = 14 g/mol, and 56 ÷ 14 = 4, so the molecule is (CH₂)₄, which is C₄H₈.', misconception: 'The belief to drop is that an empirical formula already names the molecule. It is only the simplest ratio, so C₂H₄, C₃H₆, C₄H₈ and C₅H₁₀ all share the same one, and only the molar mass separates them. Always divide the molar mass by the empirical formula mass before answering.' },
  { id: 'sto-010', tier: 2, topic: 'stoich', skill: 'stoich/solution-conc', q: 'You need 0.50 mol/L hydrochloric acid and have a 6.0 mol/L stock, the concentrated solution you dilute from. Diluting 50 mL of the stock gives 0.50 mol/L at what total volume?', opts: ['300 mL', '1200 mL', '150 mL', '600 mL'], a: 3, why: 'This is asking what final volume a dilution has to reach. Adding water adds no solute, so the moles stay fixed while the volume grows, and that is what c₁V₁ = c₂V₂ says. Here V₂ = 6.0 × 50 ÷ 0.50 = 600 mL, which is the total volume of the finished solution.', misconception: 'The belief to drop is that the answer is the volume of water to add. c₁V₁ = c₂V₂ gives the FINAL total volume, so the 50 mL of stock is made up to 600 mL, which means adding about 550 mL of water rather than 600. On a bench that difference is a standard solution about 8% out.' },
  { id: 'sto-018', tier: 2, topic: 'stoich', skill: 'stoich/solution-conc', q: 'Mix 100 mL of 1.0 mol/L NaCl with 300 mL of 2.0 mol/L NaCl. What is the final concentration?', opts: ['1.5 M', '1.25 M', '2.0 M', '1.75 M'], a: 3, why: 'This is asking for the concentration of a mixture, which always comes from total moles over total volume. Work out the moles in each portion with n = cV: 1.0 × 0.100 = 0.10 mol and 2.0 × 0.300 = 0.60 mol. Together that is 0.70 mol in 0.400 L, so the concentration is 0.70 ÷ 0.400 = 1.75 mol/L.', misconception: 'The belief to drop is that mixing two solutions gives the average of their concentrations, which would be 1.5 mol/L here. That ignores the volumes, and three times as much of the stronger solution went in. Go back to moles and total volume every time, and the answer lands closer to whichever portion is larger.' },
  { id: 'sto-033', tier: 2, topic: 'stoich', skill: 'stoich/solution-conc', q: 'What is the concentration of Na⁺ ions in a 0.10 mol/L solution of sodium sulfate, Na₂SO₄?', opts: ['0.20 mol/L', '0.10 mol/L', '0.050 mol/L', '0.30 mol/L'], a: 0, why: 'This is asking for the concentration of one ion rather than of the salt. A salt splits into its ions when it dissolves, and every formula unit of Na₂SO₄ releases two Na⁺ and one SO₄²⁻. So the sodium concentration is twice the salt\'s: 2 × 0.10 = 0.20 mol/L.', misconception: 'The belief to drop is that the figure on the bottle gives the concentration of everything in the solution. It gives the concentration of the compound, and the subscript 2 in Na₂SO₄ doubles the sodium. Split the formula into its ions first, then multiply each by its subscript.' },
  // ---- 21+ Contest ----
  { id: 'sto-007', tier: 3, topic: 'stoich', skill: 'stoich/net-ionic', q: 'Net ionic equation for mixing HCl(aq) and NaOH(aq)?', opts: ['HCl + NaOH → NaCl + H₂O', 'H⁺ + NaOH → Na⁺ + H₂O', 'Na⁺ + Cl⁻ → NaCl', 'H⁺ + OH⁻ → H₂O'], a: 3, why: 'Strong electrolytes split into ions; Na⁺ and Cl⁻ are spectators. Every strong acid + strong base gives this same net equation.' },
  { id: 'sto-008', tier: 3, topic: 'stoich', skill: 'stoich/net-ionic', q: 'Which salt is soluble in water?', opts: ['BaSO₄', 'AgCl', 'K₂CO₃', 'PbI₂'], a: 2, why: 'Group 1 and NH₄⁺ salts are ALWAYS soluble — that rule overrides "carbonates are insoluble."', misconception: 'The solubility rules are a <em>ranked</em> list, not a set of equal statements. "Group 1 and ammonium salts are always soluble" sits above "carbonates are insoluble", so K₂CO₃ dissolves despite being a carbonate. Applying the rules in the order they appear on the page, rather than by precedence, is what makes this question look ambiguous when it is not.' },
  { id: 'sto-011', tier: 3, topic: 'stoich', skill: 'stoich/empirical-formula', q: '2.50 g of CuSO₄·xH₂O leaves 1.60 g CuSO₄ (M = 159.6) after heating. x = ?', opts: ['5', '3', '7', '10'], a: 0, why: 'CuSO₄: 1.60/159.6 = 0.0100 mol; H₂O: 0.90/18 = 0.050 mol → x = 5 (blue vitriol, CuSO₄·5H₂O).', misconception: 'x is a MOLE ratio, not a mass ratio: 0.90 g of water against 1.60 g of salt looks like roughly 0.5, but water is nine times the lighter formula unit, so the mole ratio is 0.050 : 0.0100 = 5 : 1. Dividing the wrong way round — salt per water — is the other half of this trap, and it always gives an x below 1.', why2: 'Check by rebuilding the formula rather than trusting the division. CuSO₄·5H₂O has M = 159.6 + 5(18.0) = 249.6 g/mol, so the 2.50 g sample is 2.50/249.6 = 0.0100 mol — exactly the amount of CuSO₄ left behind. Any candidate x can be tested in one line this way (x = 3 would need M = 213.6 and predict 1.87 g of residue, x = 7 would need 285.6 and predict 1.40 g), and only the right one reproduces both masses at once.' },
  { id: 'sto-012', tier: 3, topic: 'stoich', skill: 'stoich/mole-concept', q: 'Volume of O₂ at STP (22.4 L/mol) needed to burn 1 mol CH₄ completely?', opts: ['22.4 L', '44.8 L', '11.2 L', '67.2 L'], a: 1, why: 'CH₄ + 2O₂ → CO₂ + 2H₂O needs 2 mol O₂ = 44.8 L.' },
  { id: 'sto-013', tier: 3, topic: 'stoich', skill: 'redox/balancing', q: 'In acidic MnO₄⁻ + Fe²⁺ titration, the mole ratio MnO₄⁻ : Fe²⁺ is…', opts: ['1:1', '1:3', '1:5', '2:5'], a: 2, why: 'Mn(+7)→Mn²⁺ gains 5 e⁻; each Fe²⁺→Fe³⁺ loses 1 → 1 permanganate oxidizes 5 iron(II). Self-indicating (purple → colorless).' },
  { id: 'sto-014', tier: 3, topic: 'stoich', skill: 'stoich/solution-conc', q: '25.0 mL of H₂SO₄ needs 40.0 mL of 0.100 M NaOH. [H₂SO₄] = ?', opts: ['0.16 M', '0.32 M', '0.04 M', '0.08 M'], a: 3, why: 'n(NaOH) = 0.00400 mol; diprotic → n(acid) = 0.00200 mol; ÷ 0.0250 L = <b>0.0800 M</b>. Forgetting the 2 gives the 0.16 trap.', misconception: 'A diprotic acid supplies two protons per molecule, so moles of base is not moles of acid. n(NaOH) = 4.00 mmol → n(H₂SO₄) = 2.00 mmol → 0.0800 M. Skipping the factor of two gives 0.16 M, exactly double, and it is the distractor placed there for that reason. Write the balanced neutralisation equation before dividing, every time.' , why2: 'Count protons, not molecules. The titration is H⁺ + OH⁻ → H₂O and nothing else, so start from what the base delivers: 40.0 mL × 0.100 M = 4.00 mmol OH⁻, therefore 4.00 mmol H⁺ was present. Each H₂SO₄ carries two of them, so the flask held 2.00 mmol of acid in 25.0 mL = <b>0.0800 M</b>. If the arithmetic ever feels ambiguous, settle the direction first: a diprotic acid needs <em>more</em> base per mole, so a fixed amount of base accounts for <em>fewer</em> moles of acid — the answer has to come out below 0.16 M, not above it.' },
  { id: 'sto-017', tier: 3, topic: 'stoich', skill: 'stoich/mole-concept', q: 'Which sample contains the MOST atoms?', opts: ['1 g of O₂', '1 g of He', '1 g of H₂', '1 g of Ne'], a: 2, why: '1 g H₂ = 0.5 mol molecules = 1 mol atoms. He: 0.25 mol atoms. Lightest particles win.', misconception: 'Equal <em>masses</em> are not equal amounts, and molecules are not atoms — this question needs both conversions. One gram of H₂ is 0.50 mol of molecules but 1.0 mol of atoms; one gram of He is only 0.25 mol of atoms. The lightest particle always wins a "most particles per gram" comparison, and forgetting the diatomic doubling is what makes it feel like a tie.' },
  { id: 'sto-019', tier: 3, topic: 'stoich', skill: 'stoich/net-ionic', q: 'Net ionic equation for Na₂CO₃(aq) + excess HCl(aq)?', opts: ['CO₃²⁻ + 2H⁺ → H₂O + CO₂', 'Na⁺ + Cl⁻ → NaCl', 'CO₃²⁻ + HCl → HCO₃⁻ + Cl⁻', 'H⁺ + OH⁻ → H₂O'], a: 0, why: 'Carbonate + strong acid fizzes CO₂. Na⁺ and Cl⁻ spectate.' },
  { id: 'sto-020', tier: 3, topic: 'stoich', skill: 'redox/oxidation-states', q: 'Oxidation state of Cr in Cr₂O₇²⁻?', opts: ['+6', '+3', '+7', '+4'], a: 0, why: '2x + 7(−2) = −2 → x = +6. Orange dichromate; reduction to green Cr³⁺ is the classic color change.' },
  { id: 'sto-021', tier: 3, topic: 'stoich', skill: 'redox/oxidation-states', q: 'Which reaction is a disproportionation?', opts: ['Zn + Cu²⁺ → Zn²⁺ + Cu', 'AgNO₃ + NaCl → AgCl + NaNO₃', '2H₂ + O₂ → 2H₂O', 'Cl₂ + 2OH⁻ → Cl⁻ + ClO⁻ + H₂O'], a: 3, why: 'Chlorine (0) is simultaneously reduced to Cl⁻ (−1) and oxidized to ClO⁻ (+1) — one element going both ways.' },
  { id: 'sto-022', tier: 3, topic: 'stoich', skill: 'stoich/solution-conc', q: '2 mg of fluoride in 1 kg of water is a concentration of…', opts: ['2 ppb', '0.2%', '2 ppm', '2 M'], a: 2, why: 'ppm = mg solute per kg solution — dilute aqueous solutions make mg/L ≈ ppm.' },
  { id: 'sto-023', tier: 3, topic: 'stoich', skill: 'stoich/solution-conc', q: 'Which measurement is needed to convert molarity to molality?', opts: ['temperature', 'solution density', 'molar mass of solute only', 'pressure'], a: 1, why: 'Molality needs kg of SOLVENT; from molarity you know volume of solution — density bridges them (then subtract the solute\'s mass).', misconception: 'Molarity is per litre of <em>solution</em>; molality is per kilogram of <em>solvent</em>. Converting between them therefore needs the density (to turn the solution\'s volume into its mass) and then the solute\'s mass subtracted off to leave the solvent. Molar mass alone is not enough, and in dilute aqueous solution the two are numerically close only because the density is near 1 — an accident of water that fails for every other solvent.' },
  { id: 'sto-025', tier: 3, topic: 'stoich', skill: 'stoich/percent-composition', q: 'A 1.00 g mixture of NaCl and KCl contains 0.60 g NaCl. Mass % Cl⁻ in the mixture ≈ ?', opts: ['45%', '35%', '60%', '55%'], a: 3, why: 'Cl from NaCl: 0.60 × 35.5/58.5 = 0.364 g; from KCl: 0.40 × 35.5/74.6 = 0.190 g → 0.554 g ≈ 55%.', misconception: 'Each salt has its own chloride mass fraction — 35.5/58.5 = 60.7% for NaCl but only 35.5/74.6 = 47.6% for KCl — so the mixture\'s figure has to be a mass-weighted blend of the two, never one of them and never a plain average. Answering 60% is quoting NaCl\'s own chloride fraction (or simply echoing the 0.60 g of NaCl) as if it described the whole sample.' },
];

export const THERMO1_QUIZ: QuizQ[] = [
  // ---- 1-10 Basics ----
  { id: 'th1-001', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'An exothermic reaction has…', opts: ['ΔH > 0', 'ΔH = 0', 'ΔH < 0', 'a beaker that gets colder'], a: 2, why: 'This is asking for the sign of ΔH when a reaction gives out heat. ΔH, the enthalpy change, is the heat taken in by the reacting system at constant pressure. An exothermic reaction releases heat instead, so the system loses energy and ΔH is negative.' },
  { id: 'th1-002', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'What are the units of specific heat capacity?', opts: ['J/mol', 'g·K/J', 'J/K only', 'J/g·K'], a: 3, why: 'This is asking for the units of specific heat capacity. Specific heat capacity is the energy needed to warm one gram of a substance by one degree. Its units are joules per gram per kelvin, J/g·K, which is what q = mcΔT needs.' },
  { id: 'th1-003', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'How much heat is needed to warm 100 g of water (c = 4.18 J/g·K) by 10 °C?', opts: ['4180 J', '418 J', '41.8 J', '41800 J'], a: 0, why: 'This is asking how much heat a given temperature rise takes. Heat equals mass × specific heat capacity × temperature change, written q = mcΔT. Here 100 × 4.18 × 10 = 4180 J, or about 4.2 kJ.' },
  { id: 'th1-004', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which process is endothermic?', opts: ['freezing water', 'melting ice', 'condensing steam', 'burning methane'], a: 1, why: 'This is asking which change absorbs heat. Endothermic means heat flows into the substance, and pulling particles apart costs energy. Melting ice breaks up the solid structure, so it takes heat in. Freezing, condensing and burning all release heat instead.' },
  { id: 'th1-005', topic: 'thermo1', skill: 'thermo/entropy', q: 'Left alone, heat flows from…', opts: ['cold to hot', 'high pressure to low', 'hot to cold', 'solid to gas'], a: 2, why: 'This is asking which way heat moves on its own. Heat always flows from the hotter object to the colder one, never the other way without help. The two end up at the same temperature, which is thermal equilibrium.' },
  { id: 'th1-026', tier: 1, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'How much heat is needed to warm 50.0 g of water (c = 4.18 J/g·K) from 20.0 °C to 30.0 °C?', opts: ['20900 J', '2090 J', '209 J', '418 J'], a: 1, why: 'This is asking how much heat a stated temperature rise costs. Heat is mass × specific heat capacity × temperature change, written q = mcΔT, where the specific heat capacity is the energy that warms one gram by one degree. Here ΔT is 30.0 − 20.0 = 10.0, so q = 50.0 × 4.18 × 10.0 = 2090 J.' },
  { id: 'th1-027', tier: 1, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Adding 1000 J to 20.0 g of water (c = 4.18 J/g·K) raises its temperature by about…', opts: ['83.6 K', '0.084 K', '12.0 K', '1.2 K'], a: 2, why: 'This is asking you to run q = mcΔT backwards, from a known heat to a temperature change. Rearranged, ΔT = q ÷ (m × c). Here m × c = 20.0 × 4.18 = 83.6 J/K, so ΔT = 1000 ÷ 83.6 = 12.0 K.' },
  { id: 'th1-028', tier: 1, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Equal masses of water (c = 4.18 J/g·K) and lead (c = 0.128 J/g·K) each absorb the same heat. Which warms up more?', opts: ['the lead, because metals conduct heat quickly', 'the water, because it can hold more heat overall', 'both rise by the same amount, since the heat is the same', 'the lead, because its specific heat capacity is much smaller'], a: 3, why: 'This is asking which substance moves further in temperature for the same energy. Specific heat capacity is the energy needed per gram per degree, so a small value means a degree is cheap. Lead\'s 0.128 J/g·K is about a thirty-third of water\'s 4.18, so the same heat drives the lead about 33 times as far.', misconception: 'How fast heat travels through something and how much heat it takes to warm are different properties. Lead conducts well, which is why it feels cold to the touch, but that has nothing to do with the answer here. Only the product m × c decides the temperature change.' },
  { id: 'th1-029', tier: 1, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Ice at 0 °C is melting while heat keeps going in. What does the temperature do?', opts: ['it stays at 0 °C until all the ice has gone', 'it climbs steadily as the heat arrives', 'it falls while the ice takes energy in', 'it holds still, then jumps once half the ice has melted'], a: 0, why: 'This is asking where the energy goes during a change of state. Melting is endothermic because pulling the particles of a solid apart costs energy, and while that is happening every joule is spent on the separation rather than on speeding particles up. So the temperature sits at the melting point until the last of the ice is gone.', misconception: 'Heat going in does not always mean a rising thermometer. During a melt or a boil the temperature is pinned at the transition, which is also why q = mcΔT cannot be used there — there is no ΔT to put in it. Melting one mole of ice takes 6.01 kJ at a flat 0 °C.' },
  { id: 'th1-030', tier: 1, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'A cold pack turns cold as the salt inside it dissolves. For that dissolving,', opts: ['ΔH is negative and the process is exothermic', 'ΔH is zero, since no reaction occurs', 'ΔH is positive and the process is endothermic', 'ΔH is positive and the process is exothermic'], a: 2, why: 'This is asking you to read a sign from an everyday observation. ΔH, the enthalpy change, is the heat taken IN by the system at constant pressure, so it is positive when the system absorbs energy. The pack feels cold because the dissolving salt is pulling heat out of your hand, which means heat flows in and ΔH is positive: endothermic.', misconception: 'The sign is written from the system\'s point of view, not the hand holding it. Something that feels cold is taking energy in, so ΔH is positive, and something that feels hot is giving energy out, so ΔH is negative. Reading the sign off your own sensation flips it every time.' },
  // ---- 11-20 Core ----
  { id: 'th1-014', tier: 2, topic: 'thermo1', skill: 'thermo/enthalpy', q: '50 g of metal at 100 °C is dropped into 100 g of water at 20 °C, and the mixture settles at 25 °C. What is the specific heat capacity of the metal?', opts: ['0.56 J/g·K', '4.18 J/g·K', '1.12 J/g·K', '0.24 J/g·K'], a: 0, why: 'This is asking you to set one substance\'s heat loss equal to the other\'s heat gain. The water gains q = 100 × 4.18 × (25 − 20) = 2090 J, and that same 2090 J is what the metal lost. The metal fell from 100 °C to 25 °C, a drop of 75 K, so c = 2090 ÷ (50 × 75) = 0.56 J/g·K.', misconception: 'The belief to drop is that both substances go through the same temperature change because they end at the same temperature. The metal falls 75 K while the water rises only 5 K, and using the wrong one of those is where the other answers come from. A metal\'s specific heat capacity is always far below water\'s 4.18, which is a useful check before writing anything down.' },
  { id: 'th1-009', tier: 2, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'You heat 10 g of ice at 0 °C until it has become water at 10 °C. Which step absorbs more heat?', opts: ['about equal', 'warming the water', 'melting the ice', 'cannot tell'], a: 2, why: 'This is asking you to compare a change of state with a temperature change. Melting takes 334 J for every gram and does not move the thermometer at all, while warming takes q = mcΔT. Melting the ice costs 10 × 334 = 3340 J and warming the water costs 10 × 4.18 × 10 = 418 J, so melting takes about eight times as much.', misconception: 'The belief to drop is that a bigger temperature change always means more heat. During a melt the temperature does not move, yet nearly all the energy goes in there — which is why a heating curve has a long flat step, and why ice keeps a drink cold far longer than the same mass of cold water does.' },
  { id: 'th1-013', tier: 2, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'During boiling, the temperature of water stays at 100 °C because the added heat…', opts: ['is destroyed', 'goes into breaking the attractions between molecules', 'speeds up molecules equally', 'escapes the pot'], a: 1, why: 'This is asking where the energy goes when the thermometer stops moving. Temperature measures how fast the molecules are moving, and boiling instead pulls the molecules away from one another against their attractions. Every joule arriving is spent on that separation until the last of the liquid has gone, so the temperature holds still.', misconception: 'The belief to drop is that heat going in must always raise a temperature. It predicts a thermometer climbing steadily through a boil. What happens instead is that the energy separates the molecules rather than speeding them up, which is why heating curves have flat steps and why steam at 100 °C scalds far worse than water at 100 °C.' },
  { id: 'th1-019', tier: 2, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Coastal cities have milder climates than inland ones mainly because water…', opts: ['reflects sunlight', 'is transparent', 'evaporates constantly', 'has a very high specific heat capacity'], a: 3, why: 'This is asking which property of water steadies a temperature. Specific heat capacity is the energy needed to warm one gram by one degree, and water\'s 4.18 J/g·K is unusually large. An ocean therefore takes in or gives out enormous amounts of heat while its own temperature barely moves, and the air above it changes slowly too.', misconception: 'The belief to drop is that this is about the sea being cold. Coastal water is often warmer than the land in winter and cooler in summer, and both follow from the same fact: it takes a great deal of energy to shift its temperature at all.' },
  { id: 'th1-020', tier: 2, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'The enthalpy of neutralisation of any strong acid with any strong base is about −57 kJ per mole of water formed, because…', opts: ['all acids are identical', 'water has a high heat capacity', 'salts are stable', 'the net reaction is always H⁺ + OH⁻ → H₂O'], a: 3, why: 'This is asking why different acids and bases give the same number. A strong acid and a strong base are both fully split into ions in solution, so the sodium, chloride, potassium and nitrate ions are only spectators. The single reaction that happens is H⁺ + OH⁻ → H₂O, and that is what the −57 kJ/mol measures.', misconception: 'The belief to drop is that a stronger or more concentrated acid gives out more heat per mole. The value is quoted per mole of water formed, and the reaction forming that water is the same one every time. A weak acid gives slightly less, because some energy is spent splitting the acid up first.' },
  { id: 'th1-010', tier: 2, topic: 'thermo1', skill: 'thermo/bond-energies', q: 'A reaction is exothermic when…', opts: ['the bonds formed are stronger than the bonds broken', 'the bonds broken are stronger than the bonds formed', 'more bonds break than form', 'the products hold more enthalpy'], a: 0, why: 'This is asking which way the energy balance falls. Breaking a bond always costs energy and making one always releases it, so a reaction gives out heat when the bonds it forms are stronger than the bonds it breaks. In general ΔH ≈ Σ(bonds broken) − Σ(bonds formed), where Σ means "add up all of", and a negative answer is an exothermic reaction.', misconception: 'The belief to drop is that the number of bonds decides the sign. A reaction can make exactly as many bonds as it breaks and still be strongly exothermic, because what matters is how strong each one is. There is also no such thing as an exothermic bond break: breaking always costs.' },
  { id: 'th1-023', tier: 2, topic: 'thermo1', skill: 'thermo/bond-energies', q: 'An estimate of ΔH from average bond enthalpies is only really valid for reactions…', opts: ['in solution', 'at 0 K', 'in the gas phase', 'with catalysts'], a: 2, why: 'This is asking what a table of bond enthalpies actually describes. A bond enthalpy is the energy needed to break one mole of that bond with everything in the gas phase, averaged over many different molecules. In a liquid or a solution there are also attractions between whole molecules to break and make, and a bond sum ignores every one of them.', misconception: 'The belief to drop is that a bond enthalpy is a fixed property of one particular bond. It is an average, so the four C–H bonds of methane are not identical and the tabulated value is a compromise between many molecules. That is why this route gives an estimate while measured data give an answer.' },
  { id: 'th1-017', tier: 2, topic: 'thermo1', skill: 'thermo/hess', q: 'Hess\'s law works because enthalpy is…', opts: ['always negative', 'a state function', 'proportional to temperature', 'a path function'], a: 1, why: 'This is asking why several small reactions can be added up to give a big one. Enthalpy is a state function, which means its change depends only on the substances you start and finish with and never on the route between them. So any set of steps that adds up to the reaction you want gives the same ΔH as the direct route would.', misconception: 'The belief to drop is that a longer route must cost more energy. Enthalpy is not like distance travelled: two routes that begin and end at the same substances give exactly the same total. That is what lets ΔH be found for a reaction nobody can carry out cleanly.' },
  { id: 'th1-022', tier: 2, topic: 'thermo1', skill: 'thermo/hess', q: 'If a reaction is written backwards, its ΔH is…', opts: ['the same as the forward value', 'the same size with the sign flipped', 'zero', 'halved'], a: 1, why: 'This is asking what reversing a reaction does to its enthalpy change. Enthalpy depends only on where you start and where you finish, so running the same change the other way retraces exactly the same gap. The size is unchanged and only the sign flips — and if the equation is also multiplied through by a number, ΔH is multiplied by that number too.', misconception: 'The belief to drop is that ΔH belongs to the chemicals rather than to the equation as written. It belongs to the equation: reverse it and the sign flips, double it and the value doubles. That is exactly what makes Hess\'s law usable.' },
  { id: 'th1-025', tier: 2, topic: 'thermo1', skill: 'thermo/hess', q: 'Given C + O₂ → CO₂ (ΔH = −393.5 kJ) and 2CO + O₂ → 2CO₂ (ΔH = −566.0 kJ), what is ΔH for C + ½O₂ → CO?', opts: ['−110.5 kJ', '−172.5 kJ', '+110.5 kJ', '−676.5 kJ'], a: 0, why: 'This is asking you to build one equation out of two known ones. Keep the first as it stands, then halve the second and reverse it: halving −566.0 gives −283.0, and reversing flips it to +283.0. Adding the two equations cancels CO₂ and leaves C + ½O₂ → CO with ΔH = −393.5 + 283.0 = −110.5 kJ.', misconception: 'The belief to drop is that −566.0 kJ is a property of carbon monoxide rather than of the equation it is written beside. Scaling the equation scales the number with it, so the second equation has to be halved before it is reversed. Reversing without halving gives −172.5 kJ, and halving without reversing gives −676.5 kJ.' },
  // ---- 21+ Contest ----
  { id: 'th1-006', tier: 3, topic: 'thermo1', skill: 'thermo/state-functions', q: 'A gas expands against constant external pressure. The sign of w for the SYSTEM is…', opts: ['positive', 'depends on temperature', 'zero', 'negative'], a: 3, why: 'w = −PₑₓₜΔV; expansion (ΔV > 0) means the system spends energy pushing the surroundings back.', misconception: 'The sign of w follows the convention w = −P_ext ΔV, written from the <em>system\'s</em> point of view. A gas that expands does work on its surroundings and loses energy, so w is negative; a gas being compressed has w positive. Reading "the gas did work, so w is positive" mixes up who is doing the work on whom, and it flips the sign of every subsequent ΔU.' },
  { id: 'th1-007', tier: 3, topic: 'thermo1', skill: 'thermo/state-functions', q: 'A bomb calorimeter (rigid, sealed) directly measures…', opts: ['ΔU', 'ΔH', 'ΔG', 'ΔS'], a: 0, why: 'Constant volume → no PV work → qᵥ = ΔU. Coffee-cup (constant P) gives ΔH.', misconception: 'A bomb calorimeter is rigid, so ΔV = 0 and no PV work is possible: what it measures is q_v = ΔU. A coffee-cup calorimeter is open to the atmosphere, constant pressure, and measures q_p = ΔH. They differ by Δn(gas)RT — small, but not zero — so quoting a bomb-calorimeter result as ΔH without correcting it is a real error, not a rounding one.' },
  { id: 'th1-008', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which species has ΔH°f = 0?', opts: ['O(g)', 'Br₂(l)', 'CO₂(g)', 'C(diamond)'], a: 1, why: 'Standard state of bromine is LIQUID Br₂. O(g) isn\'t standard (O₂ is); graphite, not diamond, is carbon\'s reference.', misconception: 'ΔH°f = 0 applies only to an element in <em>its</em> standard state — the form that is actually stable at 1 bar and 25 °C. That is Br₂(l), not Br₂(g); graphite, not diamond; O₂(g), not O(g). Diamond has ΔH°f = +1.9 kJ/mol, and treating any elemental form as a zero is the error this question is built around.' },
  { id: 'th1-011', tier: 3, topic: 'thermo1', skill: 'thermo/hess', q: 'ΔH°f: CO₂ −393.5, H₂O(l) −285.8, CH₄ −74.8 kJ/mol. ΔH° for CH₄ + 2O₂ → CO₂ + 2H₂O(l)?', opts: ['−604 kJ', '−820 kJ', '−965 kJ', '−890 kJ'], a: 3, why: 'Σproducts − Σreactants = (−393.5 − 571.6) − (−74.8) = <b>−890.3 kJ</b>. O₂ contributes 0.', misconception: 'The coefficient multiplies ΔH°f before the sum and the physical state changes the value — miss the 2 on water and you get −604, use gaseous water instead of liquid and you get −820. Reactants are SUBTRACTED, so ΔH°f(CH₄) enters as +74.8, and O₂ as an element in its standard state contributes exactly zero rather than being left out by accident.' },
  { id: 'th1-012', tier: 3, topic: 'thermo1', skill: 'thermo/state-functions', q: 'For N₂ + 3H₂ → 2NH₃ at 298 K, how do ΔH and ΔU compare?', opts: ['ΔH = ΔU', 'ΔH > ΔU', 'ΔH < ΔU', 'cannot compare'], a: 2, why: 'ΔH = ΔU + Δn(gas)RT and Δn = −2 → ΔH is LOWER by 2RT ≈ 5 kJ. Gas moles shrink, the atmosphere does work on the system.', misconception: 'ΔH and ΔU differ whenever the number of gas moles changes: ΔH = ΔU + Δn(gas)RT. For N₂ + 3H₂ → 2NH₃, Δn = −2, so ΔH is about 5 kJ/mol <em>lower</em> than ΔU at 298 K — the surroundings do work on the shrinking system. Treating the two as interchangeable is safe only when Δn(gas) = 0.' , why2: 'Watch the piston rather than the formula. ΔU is the energy the molecules themselves gained or lost; ΔH also pays for the work of shoving the atmosphere out of the way. Here 4 mol of gas become 2, so at constant pressure the vessel shrinks and the <em>atmosphere does work on the system</em>, +2RT of it. That donated work is energy the reaction does not have to supply, so the heat released at constant pressure exceeds the drop in internal energy: ΔH = ΔU − 2RT ≈ ΔU − 5 kJ, i.e. <b>ΔH &lt; ΔU</b>. The rule of thumb: gas moles shrink → surroundings push in → ΔH is the more negative of the two.' },
  { id: 'th1-015', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Why is ΔH(vaporization) much larger than ΔH(fusion)?', opts: ['gases are hotter', 'it isn\'t — they\'re similar', 'liquids have no IMFs', 'vaporization must fully separate molecules; melting only loosens them'], a: 3, why: 'Melting keeps neighbors in contact (~10% IMF loss); boiling breaks essentially ALL intermolecular attractions. Water: 6 vs 40.7 kJ/mol.' },
  { id: 'th1-016', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Standard enthalpy of formation refers to forming 1 mol of compound from…', opts: ['its ions', 'its atoms in the gas phase', 'its elements in standard states', 'any convenient reactants'], a: 2, why: 'From elements as they exist at 1 bar, 25 °C: C(graphite), O₂(g), etc. From gaseous ATOMS would be atomization — different quantity.' },
  { id: 'th1-018', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Combustion of H₂ to H₂O(l) vs to H₂O(g): which releases more heat?', opts: ['to H₂O(l)', 'to H₂O(g)', 'identical', 'depends on pressure'], a: 0, why: 'Liquid is lower in enthalpy — you additionally collect the heat of condensation (44 kJ/mol). This is the HHV/LHV fuel distinction.', misconception: 'Burning to liquid water releases more heat than burning to steam, by the enthalpy of condensation (about 44 kJ per mole of water). That is exactly the higher/lower heating value distinction quoted for fuels: the HHV assumes the water in the exhaust is condensed and its heat recovered, the LHV assumes it leaves as vapour. Writing "H₂O" in a combustion equation without deciding its state leaves ΔH ambiguous by tens of kJ.' },
  { id: 'th1-021', tier: 3, topic: 'thermo1', skill: 'thermo/state-functions', q: 'In which process is w = 0?', opts: ['reaction in a rigid sealed vessel', 'gas compressed by a piston', 'gas expands against 1 atm', 'gas expands a balloon'], a: 0, why: 'No volume change → no PV work. All energy exchange is heat: ΔU = q.' },
  { id: 'th1-024', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which requires the input of energy?', opts: ['H(g) + H(g) → H₂(g)', 'Cl(g) + e⁻ → Cl⁻(g)', 'Na⁺(g) + Cl⁻(g) → NaCl(s)', 'Na(g) → Na⁺(g) + e⁻'], a: 3, why: 'Ionization energy is always positive (endothermic). The other three release energy (EA of Cl, lattice energy, bond formation).' },
];

export const THERMO2_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'th2-001', topic: 'thermo2', skill: 'thermo/entropy', q: 'Entropy is best described as a measure of…', opts: ['the heat content', 'the average bond strength', 'the absolute temperature', 'accessible microstates'], a: 3, why: 'This is asking what entropy actually measures. Entropy, S, counts how many microscopic arrangements, called microstates, give the same overall state. Boltzmann wrote this as S = k ln W, where W is that number of arrangements.', misconception: 'Entropy is not "disorder", and that word will mislead you on a real problem. It counts how many microscopic arrangements are consistent with what you can measure — a matter of <em>how the energy and particles can be distributed</em>, not how untidy something looks. The tell: dissolving a gas in water has ΔS &lt; 0, and so does dissolving many salts, even though the neat crystal visibly breaks up. Count states, don\'t picture mess.' },
  { id: 'th2-002', topic: 'thermo2', skill: 'thermo/entropy', q: 'Which phase of water has the highest entropy?', opts: ['ice', 'liquid', 'steam', 'all equal'], a: 2, why: 'This is asking which phase has the most ways to arrange its molecules. Entropy rises when molecules have more room and more freedom to move. Steam molecules roam the whole container, so gas beats liquid, and liquid beats ice.' },
  { id: 'th2-003', topic: 'thermo2', skill: 'thermo/gibbs', q: 'A reaction is spontaneous when…', opts: ['ΔG > 0', 'ΔG < 0', 'ΔH < 0 always', 'ΔS < 0'], a: 1, why: 'This is asking what makes a reaction go on its own. The test is ΔG, the Gibbs energy change, which combines the heat change and the entropy change as ΔG = ΔH − TΔS. At constant temperature and pressure a reaction is spontaneous when ΔG is negative.' },
  { id: 'th2-004', topic: 'thermo2', skill: 'thermo/entropy', q: 'The sign of ΔS for melting is…', opts: ['positive', 'negative', 'zero', 'depends on the substance'], a: 0, why: 'This is asking for the sign of the entropy change when a solid melts. Entropy rises when the molecules gain more ways to arrange themselves. In a liquid they can slide past one another, so melting increases entropy and ΔS is positive.' },
  { id: 'th2-005', topic: 'thermo2', skill: 'thermo/entropy', q: 'The third law says S = 0 for…', opts: ['any ideal gas at STP', 'pure elements at 25 °C', 'liquid water at 0 °C', 'a perfect crystal at 0 K'], a: 3, why: 'This is asking when entropy is exactly zero. Entropy counts the arrangements available, and a flawless crystal at absolute zero has only one. With W = 1, S = k ln 1 = 0, which sets the zero point for all absolute entropies.' },
  // ---- olympiad ----
  { id: 'th2-006', topic: 'thermo2', skill: 'thermo/entropy', q: 'Which reaction has ΔS > 0?', opts: ['N₂(g) + 3H₂(g) → 2NH₃(g)', 'H₂O(g) → H₂O(l), condensing', '2H₂O₂(l) → 2H₂O(l) + O₂(g)', 'CO₂(g) → CO₂(s), depositing'], a: 2, why: 'Count gas moles: liquid → liquid + GAS creates gas from none. The others reduce or condense.' },
  { id: 'th2-007', tier: 3, topic: 'thermo2', skill: 'thermo/gibbs', q: 'ΔH < 0 and ΔS < 0. The reaction is spontaneous…', opts: ['at all temperatures', 'only at LOW temperature', 'never', 'only at HIGH temperature'], a: 1, why: 'ΔG = ΔH − TΔS: the favorable ΔH wins at small T; the unfavorable −TΔS takes over above T = ΔH/ΔS.', misconception: 'ΔH &lt; 0 with ΔS &lt; 0 is not "never spontaneous" — it is spontaneous at LOW temperature only. In ΔG = ΔH − TΔS the −TΔS term is unfavourable and grows with T, so the reaction turns off above T = ΔH/ΔS rather than switching on. Two of the four sign quadrants are temperature-dependent, and getting the direction of the switch backwards is the usual error.' },
  { id: 'th2-008', topic: 'thermo2', skill: 'thermo/gibbs', q: 'At equilibrium, which quantity equals zero?', opts: ['ΔG', 'ΔG°', 'ΔS', 'K'], a: 0, why: 'ΔG = 0 — no net driving force. ΔG° is a fixed constant (zero only if K = 1).', misconception: 'ΔG° and ΔG are different quantities, and the degree symbol is doing real work. ΔG° is a single fixed number for the reaction — everything at standard states — and it fixes K through ΔG° = −RT ln K. ΔG is the driving force <em>right now</em>, at whatever Q the mixture currently sits at: ΔG = ΔG° + RT ln Q. So a reaction with ΔG° > 0 is <em>not</em> "impossible"; it simply has K &lt; 1 and still runs forward until Q reaches K.' },
  { id: 'th2-009', topic: 'thermo2', skill: 'thermo/gibbs', q: 'If ΔG° = 0 at 298 K, then K is…', opts: ['0', 'negative', '∞', '1'], a: 3, why: 'ΔG° = −RT ln K → ln K = 0 → K = 1.' },
  { id: 'th2-010', topic: 'thermo2', skill: 'thermo/entropy', q: 'Highest standard molar entropy at 298 K?', opts: ['He(g)', 'C₂H₆(g)', 'H₂O(l)', 'NaCl(s)'], a: 1, why: 'Gas beats liquid beats solid; among gases, more atoms = more rotations/vibrations to store energy in.', misconception: 'Phase is the first thing to check for entropy, but among substances in the <em>same</em> phase it decides nothing. Ethane and helium are both gases; C₂H₆ has far more entropy (229 versus 126 J/mol·K) because a polyatomic molecule has rotations and vibrations to store energy in, and a monatomic gas has none. More atoms per molecule means more ways to distribute the same energy.' },
  { id: 'th2-011', tier: 3, topic: 'thermo2', skill: 'thermo/entropy', q: 'ΔH(vap) of water = 40.7 kJ/mol at 373 K. ΔS(vap) ≈ ?', opts: ['40.7 J/mol·K', '9.2 J/mol·K', '109 J/mol·K', '373 J/mol·K'], a: 2, why: 'At the normal bp the phases are in equilibrium: ΔG = 0 → ΔS = ΔH/T = 40700/373 ≈ <b>109 J/mol·K</b>.', misconception: 'ΔS = ΔH/T is legitimate here only because the two phases are at equilibrium at the normal boiling point (ΔG = 0), and it is only correct in consistent units — 40.7 kJ must become 40 700 J. Dividing the other way round, T/ΔH, gives 9.2, and quoting 40.7 J/mol·K is copying the enthalpy value across as though entropy shared its scale. Trouton\'s rule says the answer should land near 85–110 J/mol·K for almost any liquid.' },
  { id: 'th2-012', tier: 3, topic: 'thermo2', skill: 'thermo/gibbs', q: 'CaCO₃ → CaO + CO₂: ΔH° = +178 kJ, ΔS° = +160 J/K. Decomposition becomes spontaneous above…', opts: ['298.0 K', 'about 500 K', 'never at any T', '~1110 K, where ΔG turns'], a: 3, why: 'T = ΔH/ΔS = 178000/160 ≈ 1113 K (~840 °C) — why limestone kilns run hot.', misconception: 'With ΔH and ΔS both positive there is always a crossover temperature, so "never spontaneous" is a sign-reading error — the reaction is simply non-spontaneous while TΔS is smaller than ΔH. The other trap is units: ΔH is in kJ and ΔS in J/K, and 178/160 gives a nonsensical 1.1 K where 178 000/160 gives the real 1113 K.' },
  { id: 'th2-013', topic: 'thermo2', skill: 'thermo/entropy', q: 'An exothermic reaction increases the entropy of the SURROUNDINGS because…', opts: ['released heat disperses outward', 'it orders the product molecules', 'ΔS of the system must be positive', 'the temperature falls as it goes'], a: 0, why: 'ΔSsurr = −ΔH/T > 0 when ΔH < 0. This term is why many exothermic reactions are spontaneous even with ΔSsys < 0.', misconception: 'The second law constrains the entropy of the <em>universe</em>, not of the system. An exothermic reaction dumps heat into its surroundings, raising their entropy by ΔS_surr = −ΔH/T — and that term is often what makes ΔS_universe positive even when the system itself becomes more ordered. Judging spontaneity from ΔS_sys alone is why "exothermic reactions that lose entropy" look impossible when they are routine.' },
  { id: 'th2-014', topic: 'thermo2', skill: 'thermo/gibbs', q: 'NH₄NO₃ dissolves spontaneously although the beaker gets COLD. The process is driven by…', opts: ['enthalpy', 'entropy', 'pressure', 'a catalyst'], a: 1, why: 'ΔH > 0 (endothermic — cold packs!) but the ions dispersing through water give ΔS ≫ 0, making ΔG < 0.', misconception: 'Endothermic does not mean non-spontaneous. NH₄NO₃ dissolving takes heat from the beaker (that is what makes an instant cold pack work), but the ions dispersing through the solvent give a large positive ΔS, and TΔS outweighs ΔH. Spontaneity is decided by ΔG, and using ΔH as a proxy for it fails for exactly this class of process.' },
  { id: 'th2-015', topic: 'thermo2', skill: 'equilibrium/le-chatelier', q: 'For an exothermic reaction, raising the temperature makes K…', opts: ['larger', 'unchanged', 'smaller', 'exactly 1'], a: 2, why: 'van \'t Hoff: ln K falls as T rises when ΔH° < 0 — heat is a "product," so adding it pushes back.' , why2: 'Put numbers on van \'t Hoff and the direction stops being a memory item. Take ΔH° = −50 kJ/mol with ΔS° = 0: K = e<sup>−ΔH°/RT</sup> gives e<sup>20.2</sup> ≈ 6×10⁸ at 298 K, but only e<sup>15.1</sup> ≈ 4×10⁶ at 398 K — a 160-fold collapse for a 100 K rise. Microscopically, heating populates higher-energy states, which always favours whichever direction is <em>endothermic</em>; for an exothermic forward reaction that is the reverse, so K falls. Note what does not change: ΔH° and ΔS° are (near enough) constant, and it is only the balance between them in ΔG° = ΔH° − TΔS° that T is rewriting.' },
  { id: 'th2-016', topic: 'thermo2', skill: 'thermo/gibbs', q: 'K = 100 at 298 K. ΔG° ≈ ?', opts: ['−2.5 kJ/mol', '+11.4 kJ/mol', '−100 kJ/mol', '−11.4 kJ/mol'], a: 3, why: 'ΔG° = −RT ln K = −8.314 × 298 × ln(100) = −11.4 kJ/mol. Each factor of 10 in K ≈ 5.7 kJ/mol at 25 °C.' },
  { id: 'th2-017', topic: 'thermo2', skill: 'thermo/gibbs', q: 'ΔG° > 0 for a reaction. This means…', opts: ['K < 1, but some product still forms', 'no product is ever formed', 'the reverse reaction is fast', 'ΔH is necessarily positive'], a: 0, why: 'ΔG° sets WHERE equilibrium sits, not whether anything happens. Some product always forms.' },
  { id: 'th2-018', topic: 'thermo2', skill: 'thermo/entropy', q: 'Sign of ΔS° for 2H₂(g) + O₂(g) → 2H₂O(g)?', opts: ['positive', 'negative', 'zero', 'cannot tell'], a: 1, why: '3 mol gas → 2 mol gas — fewer gas particles, fewer microstates, ΔS < 0. (Still spontaneous: huge −ΔH.)' },
  { id: 'th2-019', topic: 'thermo2', skill: 'thermo/entropy', q: 'Living organisms build ordered structures without violating the second law because…', opts: ['biology is exempt from it', 'their total ΔS is zero', 'they export more entropy than they lose', 'the enzymes change K'], a: 2, why: 'ΔS(universe) = ΔS(organism) + ΔS(surroundings) > 0 — metabolizing food dumps plenty of entropy into the environment.', misconception: 'Building an ordered organism does not break the second law, because an organism is not an isolated system. It exports far more entropy to its surroundings — as heat, CO₂ and waste — than it removes internally, so ΔS_universe still rises. The rule that entropy must increase applies only to isolated systems; any open system can lower its own entropy by raising something else\'s more.' },
  { id: 'th2-020', tier: 3, topic: 'thermo2', skill: 'thermo/entropy', q: 'Which has the higher S°: O₂(g) or O₃(g), per mole?', opts: ['O₂', 'equal', 'O₃', 'not comparable'], a: 2, why: 'More atoms per molecule = more vibrational and rotational modes to store energy in = more entropy. S°(O₃) = 239 J/mol·K vs S°(O₂) = 205 J/mol·K. Both are gases, so the phase rule of thumb can\'t separate them — molecular complexity does.', misconception: 'Entropy is not a ranking of stability or reactivity — O₂ being the stable allotrope says nothing about its S°. Both species are gases, so the phase rule of thumb is silent and molecular complexity decides: the triatomic has more rotational and vibrational modes to spread energy over, giving O₃ the larger standard entropy.' },
  { id: 'th2-021', topic: 'thermo2', skill: 'thermo/gibbs', q: 'ATP hydrolysis (ΔG° = −30 kJ) drives amino-acid coupling (ΔG° = +14 kJ). The combined ΔG° is…', opts: ['+44 kJ', '−16 kJ', '−44 kJ', '+16 kJ'], a: 1, why: 'Coupled reactions add their ΔG°: −30 + 14 = −16 kJ < 0 → spontaneous. Free-energy accounting is additive.' },
  { id: 'th2-022', topic: 'thermo2', skill: 'thermo/gibbs', q: 'Diamond → graphite has ΔG° < 0, yet diamonds persist because…', opts: ['the activation barrier is enormous', 'ΔG° is in fact positive here', 'diamond is pure carbon already', 'entropy forbids the change'], a: 0, why: 'Thermodynamics says "downhill", kinetics says "not in a billion years." Spontaneous ≠ fast.', misconception: 'Spontaneous means thermodynamically downhill; it says nothing whatever about speed. Diamond → graphite has ΔG° &lt; 0 at room temperature and yet takes geological time, because the activation barrier for rearranging the carbon lattice is enormous. Every question that mixes ΔG with a rate is testing this: thermodynamics decides the destination, kinetics decides whether you arrive this century.' },
  { id: 'th2-023', topic: 'thermo2', skill: 'thermo/entropy', q: 'One mole of ideal gas doubles its volume isothermally. ΔS = ?', opts: ['2R exactly', 'zero, isothermal', 'R alone', 'R ln 2, about 5.76 J/K'], a: 3, why: 'ΔS = nR ln(V₂/V₁) = R ln 2. Twice the space = 2^N times the microstates for N particles.' },
  { id: 'th2-024', topic: 'thermo2', skill: 'thermo/gibbs', q: 'If Q < K, then ΔG for the reaction as written is…', opts: ['positive', 'zero', 'negative', 'equal to ΔG°'], a: 2, why: 'ΔG = RT ln(Q/K); Q/K < 1 → ln negative → forward reaction is downhill until Q = K.' },
  { id: 'th2-025', topic: 'thermo2', skill: 'thermo/gibbs', q: 'Which pair makes spontaneity GUARANTEED at every temperature?', opts: ['ΔH > 0, ΔS > 0', 'ΔH < 0, ΔS > 0', 'ΔH < 0, ΔS < 0', 'ΔH > 0, ΔS < 0'], a: 1, why: 'Both terms of ΔG = ΔH − TΔS are then negative at any T. (The opposite corner is never spontaneous.)' },
];

export const EQUILIBRIUM_QUIZ: QuizQ[] = [
  // ---- 1-10 Basics ----
  { id: 'equ-001', topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'At equilibrium…', opts: ['forward and reverse rates are equal', 'all reactions stop', 'concentrations of products and reactants are equal', 'K = 0'], a: 0, why: 'This is asking what actually stays constant at equilibrium. Equilibrium is dynamic, so the forward and reverse reactions both keep running. Their rates become equal, so the concentrations stop changing. Those concentrations are rarely equal to each other.', misconception: 'Equilibrium means equal <em>rates</em>, not equal concentrations. Forward and reverse reactions both continue at matching speeds, so the composition stops changing at whatever ratio K dictates — which is usually nowhere near 1:1. "Nothing is happening" and "there is as much product as reactant" are two different wrong pictures of the same idea.' },
  { id: 'equ-002', topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'K ≫ 1 means that at equilibrium…', opts: ['reactants dominate', 'products dominate', 'nothing reacted', 'the reaction is fast'], a: 1, why: 'This is asking what a large equilibrium constant tells you. K, the equilibrium constant, is the ratio of product amounts to reactant amounts once the reaction settles. A K far above 1 makes that ratio large, so products dominate. K says nothing about how fast the mixture gets there.', misconception: 'K measures how far a reaction goes, not how fast it gets there. A reaction with K = 10¹⁰ can be immeasurably slow (hydrogen and oxygen sit together indefinitely at room temperature), and a reaction with K near 1 can be over in microseconds. Nothing in an equilibrium constant contains a rate constant except their ratio, K = kf/kr.' },
  { id: 'equ-003', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'Adding a catalyst changes K by…', opts: ['increasing it', 'decreasing it', 'nothing', 'doubling it'], a: 2, why: 'This is asking whether a catalyst changes the final mixture. A catalyst lowers the energy barrier for the forward and reverse reactions by the same amount. Both speed up equally, so the balance point is untouched and K is unchanged.', misconception: 'A catalyst does not improve <em>yield</em>, only the <em>time</em> taken to reach it. It lowers the activation barrier for the forward and reverse reactions by the same amount, so kf and kr rise in step and K = kf/kr is untouched. A catalysed reaction and an uncatalysed one arrive at exactly the same final mixture; one just gets there sooner.' },
  { id: 'equ-004', topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'Pure solids appear in the equilibrium expression as…', opts: ['their concentration', 'their mass', 'their volume', 'they are omitted'], a: 3, why: 'This is asking how a pure solid enters the equilibrium expression. The expression uses concentrations that can change, and a pure solid keeps the same density however much of it is there. Its value is constant and is folded into K, so pure solids and pure liquids are left out.' },
  { id: 'equ-005', topic: 'equilibrium', skill: 'equilibrium/q-vs-k', q: 'If Q = K, the system…', opts: ['is at equilibrium', 'shifts to the left', 'shifts to the right', 'runs away entirely'], a: 0, why: 'This is asking what it means when Q equals K. Q, the reaction quotient, is the same ratio as K but worked out from the amounts present right now. When Q and K match, the mixture already has its equilibrium composition, so nothing shifts.' },
  { id: 'equ-026', tier: 1, topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), the equilibrium constant is…', opts: ['(2[SO₃]) ÷ (2[SO₂] + [O₂])', '[SO₃] ÷ ([SO₂][O₂])', '([SO₂]²[O₂]) ÷ [SO₃]²', '[SO₃]² ÷ ([SO₂]²[O₂])'], a: 3, why: 'This is asking you to build K from a balanced equation. K, the equilibrium constant, is products over reactants, with every concentration raised to the power of its own coefficient. Products go on top, so [SO₃] is squared above [SO₂] squared times [O₂].', misconception: 'A coefficient becomes an EXPONENT in the equilibrium expression, never a multiplier and never a term to add. Writing 2[SO₃] instead of [SO₃]² changes the value of K by orders of magnitude once concentrations move away from 1 M. Read each coefficient as "raise this concentration to that power".' },
  { id: 'equ-027', tier: 1, topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'A flask of N₂O₄(g) ⇌ 2NO₂(g) settles at [NO₂] = 0.40 M and [N₂O₄] = 0.80 M. What is K?', opts: ['0.20', '0.50', '0.32', '2.0'], a: 0, why: 'This is asking you to put numbers into an equilibrium expression. Here K = [NO₂]² ÷ [N₂O₄], because the coefficient 2 in the equation becomes the power on NO₂. So K = 0.40² ÷ 0.80 = 0.16 ÷ 0.80 = 0.20.', misconception: 'Dropping the square is the single most common slip here, and it gives 0.40 ÷ 0.80 = 0.50 — a plausible-looking number with no way to spot the error afterwards. Write the expression out with its exponents before any digit is entered on the calculator.' },
  { id: 'equ-028', tier: 1, topic: 'equilibrium', skill: 'equilibrium/q-vs-k', q: 'A mixture has Q = 2.0 while K = 8.0. What happens next?', opts: ['it runs backward, making more reactant', 'it runs forward, making more product', 'nothing — it is already at equilibrium', 'the reaction stops entirely'], a: 1, why: 'This is asking which way a mixture that is not yet at equilibrium will move. Q, the reaction quotient, is the same fraction as K but worked out from the amounts present right now. Q below K means the top of the fraction is too small, so there is too little product and the reaction runs forward until the two match.' },
  { id: 'equ-029', tier: 1, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'Which of these changes the VALUE of K?', opts: ['adding more of a reactant', 'adding a catalyst', 'raising the temperature', 'squeezing a gas mixture into half the volume'], a: 2, why: 'This is asking you to separate a shift in the mixture from a change in the constant itself. Adding, removing or squeezing changes the amounts present, so the mixture shifts until the same K is satisfied again. Temperature is the one change that gives K a different value, because K is fixed only for one reaction at one temperature.', misconception: 'Every Le Châtelier stress makes the mixture move, and only one of them moves K. Add reactant and the system shifts right, but it shifts until the ratio returns to exactly the K it started with. Heating N₂O₄ favours the split into NO₂ and genuinely raises K, which is why the gas darkens when warmed.' },
  { id: 'equ-030', tier: 1, topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'Which species appear in the equilibrium expression for CaCO₃(s) ⇌ CaO(s) + CO₂(g)?', opts: ['CO₂ only', 'CaO and CO₂', 'all three', 'CaCO₃ only'], a: 0, why: 'This is asking which species have a concentration that can change. A pure solid keeps the same density however much of it sits in the flask, so its value is constant and is folded into K. Both solids drop out, leaving only the gas: K = [CO₂].', misconception: 'Leaving a solid out is not the same as pretending it is absent. The reaction needs solid CaCO₃ present to have an equilibrium at all — it simply contributes a fixed number that lives inside K. Adding more limestone to the flask therefore shifts nothing.' },
  // ---- 11-20 Core ----
  { id: 'equ-011', tier: 2, topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'For which reaction is Kp equal to Kc?', opts: ['N₂ + 3H₂ ⇌ 2NH₃', 'H₂ + I₂ ⇌ 2HI', 'PCl₅ ⇌ PCl₃ + Cl₂', 'CaCO₃ ⇌ CaO + CO₂'], a: 1, why: 'This is asking when the two forms of the equilibrium constant give the same number. Kc is built from concentrations and Kp from partial pressures, and the two are linked by Kp = Kc(RT)^Δn, where Δn is the moles of gas on the right minus the moles on the left. When Δn is zero that factor is (RT)⁰ = 1, and H₂ + I₂ ⇌ 2HI has two moles of gas on each side.', misconception: 'The belief to drop is that Kp and Kc are two names for one number. They differ by a factor of (RT)^Δn, which is about 24 for every net mole of gas at room temperature, so quoting one where the other is wanted can be out by orders of magnitude. Count the gas moles on each side before assuming they are equal.' },
  { id: 'equ-012', tier: 2, topic: 'equilibrium', skill: ['equilibrium/ice-setup', 'equilibrium/k-expression'], q: 'For N₂O₄ ⇌ 2NO₂, starting from 1.0 mol/L N₂O₄ with x mol/L reacting, which is the correct K expression?', opts: ['(2x)²/(1−x)', 'x²/(1−x), with no factor', '2x/(1−x), unsquared', '4x/(1−x)², inverted'], a: 0, why: 'This is asking you to build an ICE table and put it into K. The change row follows the coefficients, so N₂O₄ falls by x while NO₂ rises by 2x, leaving 1 − x and 2x at equilibrium. K is products over reactants with each concentration raised to its own coefficient, so K = (2x)² ÷ (1 − x), which is 4x² ÷ (1 − x).', misconception: 'The belief to drop is that a coefficient is used once. It has two separate jobs: it scales the change row, making the NO₂ term 2x rather than x, and it becomes the exponent in K. Using it only as the exponent gives x²/(1 − x) and quietly loses a factor of four.' },
  { id: 'equ-018', tier: 2, topic: 'equilibrium', skill: 'equilibrium/approximations', q: 'The "small x" shortcut, dropping x from (C₀ − x), is safe when…', opts: ['K is very large', 'the temperature is low', 'x is under 5% of the starting concentration', 'the reaction happens to be exothermic'], a: 2, why: 'This is asking when it is safe to simplify an ICE calculation. Dropping x from the bottom of the expression is an approximation, and it holds only while x is small enough that the starting concentration is barely changed. The working rule is to solve first and check afterwards: if x is under 5% of the starting concentration, keep the answer, and if not, solve the full quadratic.', misconception: 'The belief to drop is that the check can be made in advance from the size of K alone. A small K usually does mean a small x, but the starting concentration matters too — the same K passes the 5% test at 1.00 mol/L and fails it at 0.100 mol/L. Always solve, then divide x by the starting concentration.' },
  { id: 'equ-014', tier: 2, topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'CaCO₃(s) ⇌ CaO(s) + CO₂(g) is at equilibrium. Adding more solid CaCO₃…', opts: ['shifts it right', 'shifts it left', 'does nothing', 'raises the pressure of CO₂'], a: 2, why: 'This is asking which species can appear in an equilibrium expression. A pure solid keeps the same density however much of it is present, so its value is constant and is folded into K. Here K = [CO₂] alone, so a mountain of limestone gives exactly the same answer as a pinch and nothing shifts.', misconception: 'The belief to drop is that leaving a solid out of K means the solid does not matter. Some has to be there for the equilibrium to exist at all; what does not matter is how much. The amount of CO₂ above it is set by the temperature alone.' },
  { id: 'equ-006', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'An unreactive gas such as argon is added to a gas mixture at CONSTANT VOLUME. The equilibrium…', opts: ['shifts toward fewer gas moles', 'does not shift at all', 'shifts toward more gas moles', 'shifts toward products'], a: 1, why: 'This is asking whether the total pressure or the individual concentrations are what matters. K is built from the concentrations of the reacting gases, and pouring argon into a sealed flask of fixed volume changes none of them. Q therefore still equals K, and nothing shifts.', misconception: 'The belief to drop is that raising the pressure always pushes an equilibrium toward the side with fewer gas molecules. What does that is squeezing the volume, because that raises every concentration at once. Argon raises the total pressure while leaving each reacting gas exactly where it was, so always ask what happened to the individual gases rather than to the total.' },
  { id: 'equ-023', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'For N₂ + 3H₂ ⇌ 2NH₃, compressing the mixture at constant temperature shifts it…', opts: ['right', 'left', 'not at all', 'to pure NH₃'], a: 0, why: 'This is asking what squeezing a gas mixture does. Halving the volume doubles every concentration at once, and the side holding more gas molecules is affected more, so the mixture relieves the squeeze by moving toward the side with fewer. Here four moles of gas become two, so compression shifts the equilibrium to the right.', misconception: 'The belief to drop is that pressure changes K. Compressing the flask changes the concentrations, so Q no longer matches K and the mixture moves — but it moves until it satisfies exactly the K it always had. Only temperature rewrites K itself.' },
  { id: 'equ-010', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'An endothermic reaction is heated. Its equilibrium constant K…', opts: ['decreases', 'is unchanged', 'increases', 'becomes negative'], a: 2, why: 'This is asking which way temperature moves K for a reaction that takes heat in. An endothermic reaction absorbs energy as it goes forward, so heat behaves like one of its reactants. Supplying more of it pushes the balance point toward the products, and because temperature is the one change that rewrites K, the value of K itself rises.', misconception: 'The belief to drop is that heating always raises a yield. Heating speeds both directions up, and which way the balance moves depends on the sign of ΔH. For an exothermic reaction, heating lowers K.' },
  { id: 'equ-024', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'K rises from 10 to 1000 when the temperature goes from 300 K to 400 K. The reaction is…', opts: ['exothermic overall', 'endothermic, with K rising as T rises', 'athermal, ΔH = 0', 'thermodynamically impossible'], a: 1, why: 'This is asking you to read the sign of ΔH off two values of K. Heat acts like a reactant for an endothermic reaction and like a product for an exothermic one. K climbing as the temperature climbs means the extra heat is favouring the products, so the forward reaction takes heat in and ΔH is positive.', misconception: 'The belief to drop is that heating always increases a yield. It increases K only for an endothermic reaction; for an exothermic one, heating lowers K. That is the compromise behind running ammonia synthesis hot: the yield is worse, but the reaction is fast enough to be worth doing.' },
  { id: 'equ-007', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'Which is the only change that alters the value of K itself?', opts: ['adding more reactant', 'changing the volume', 'changing the temperature', 'adding a catalyst'], a: 2, why: 'This is asking you to separate the mixture moving from the constant changing. K is fixed for one reaction at one temperature, so adding a reactant, squeezing the flask or adding a catalyst only displaces Q, and the mixture then shifts until Q matches the same K again. Only a change of temperature gives K a new value.', misconception: 'The belief to drop is that "the equilibrium shifted" and "K changed" are the same statement. Almost every disturbance shifts the mixture and leaves K exactly where it was. Heating N₂O₄ genuinely raises K, which is why the gas visibly darkens when it is warmed.' },
  { id: 'equ-021', tier: 2, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'A catalyst is added to a mixture that is already at equilibrium. The result is…', opts: ['a shift to the right', 'a shift to the left', 'no change in composition', 'a rise in the value of K'], a: 2, why: 'This is asking whether a catalyst can improve a yield. A catalyst offers a route over a lower energy barrier, and that barrier lies between the same two sides in both directions, so the forward and reverse reactions speed up by the same factor. The point where the two rates match is therefore unchanged, and a mixture already sitting there does not move at all.', misconception: 'The belief to drop is that anything which speeds a reaction up must also produce more product. A catalyst changes the time taken and never the destination. A catalysed and an uncatalysed reaction finish at exactly the same mixture.' },
  // ---- 21+ Contest ----
  { id: 'equ-008', tier: 3, topic: 'equilibrium', skill: ['equilibrium/ksp', 'equilibrium/k-expression'], q: 'A₂B(s) ⇌ 2A⁺ + B²⁻ with molar solubility s = 1×10⁻³ M. Ksp = ?', opts: ['1×10⁻⁶', '1×10⁻⁹', '2×10⁻⁶', '4×10⁻⁹'], a: 3, why: 'Ksp = (2s)²(s) = 4s³ = 4×10⁻⁹. Forgetting the 2 inside the square is THE classic error.', misconception: 'A stoichiometric coefficient does double duty in a Ksp expression, and dropping either use is the classic error. For A₂B ⇌ 2A⁺ + B²⁻, the 2 multiplies the solubility <em>and</em> becomes the exponent: Ksp = (2s)²(s) = 4s³, not s³ or 2s³. Write the ICE row explicitly rather than lifting exponents straight off the equation.' },
  { id: 'equ-009', tier: 2, topic: 'equilibrium', skill: 'equilibrium/q-vs-k', q: 'Q < K means the reaction will…', opts: ['proceed forward', 'proceed reverse', 'stay put', 'reach Q = 0'], a: 0, why: 'This is asking which way a mixture that is not yet settled will move. Q is the same expression as K but worked out from what is in the flask right now, so Q below K means there is too little product. The reaction runs forward until Q has climbed to meet K.' },
  { id: 'equ-013', tier: 3, topic: 'equilibrium', skill: 'equilibrium/k-manipulation', q: 'If K = 4 for A ⇌ B, then K for 2B ⇌ 2A is…', opts: ['1/4, reciprocal', '1/2, square root', '−4, sign flipped', '1/16, squared and inverted'], a: 3, why: 'Reverse → reciprocal (1/4); double → square it: (1/4)² = 1/16.', misconception: 'Reversing and scaling act on K in different ways and this question applies both: reversing takes the reciprocal, multiplying the equation through by n raises K to the nth power. Stopping at 1/4 handles the reversal and forgets the doubling, while 1/2 takes the square ROOT — the exponent applied upside down. Doubling an equation squares its K; it never doubles or halves it.' },
  { id: 'equ-015', tier: 3, topic: 'equilibrium', skill: 'equilibrium/k-manipulation', q: 'K for a reaction that is the SUM of two steps equals…', opts: ['K₁ + K₂', 'K₁ × K₂', 'K₁ − K₂', 'K₁/K₂'], a: 1, why: 'Adding equations multiplies their K\'s (free energies add → exponentials multiply).' },
  { id: 'equ-016', tier: 3, topic: 'equilibrium', skill: ['equilibrium/ksp', 'equilibrium/le-chatelier'], q: 'AgCl solubility in 0.1 M NaCl compared to pure water is…', opts: ['much lower', 'exactly the same', 'somewhat higher', 'effectively zero'], a: 0, why: 'Common-ion effect: s = Ksp/[Cl⁻] = 1.8×10⁻¹⁰/0.1 = 1.8×10⁻⁹ M — about 10,000× less than in pure water.' },
  { id: 'equ-017', tier: 3, topic: 'equilibrium', skill: 'equilibrium/ksp', q: 'Equal concentrations of Cl⁻ and I⁻; AgNO₃ is dripped in slowly. Which precipitates first?', opts: ['AgCl (Ksp 1.8×10⁻¹⁰)', 'neither', 'both together', 'AgI (Ksp 8.5×10⁻¹⁷)'], a: 3, why: 'Same 1:1 stoichiometry → the smaller Ksp is exceeded first. AgI is ~10⁷× less soluble — the basis of selective precipitation.', misconception: 'A larger Ksp means MORE soluble, so it takes a higher Ag⁺ concentration before that solid appears — the smaller Ksp precipitates first, not the more familiar salt. Comparing Ksp values head-to-head is only legitimate because both salts here are 1:1; for salts of different stoichiometry (AgCl against Ag₂CrO₄) you must convert to molar solubilities before ranking them.', why2: 'Read it as a threshold concentration instead of a comparison of constants. If both halides start at 0.010 M, AgI begins to form once [Ag⁺] = 8.5×10⁻¹⁷/0.010 = 8.5×10⁻¹⁵ M, while AgCl needs 1.8×10⁻¹⁰/0.010 = 1.8×10⁻⁸ M — seven orders of magnitude later. That gap is what makes the separation quantitative: by the time enough Ag⁺ has been added to touch the chloride, the iodide remaining in solution is down at ~5×10⁻⁹ M, essentially all of it already on the bottom of the flask.' },
  { id: 'equ-019', tier: 3, topic: 'equilibrium', skill: 'equilibrium/ksp', q: 'Mg(OH)₂ is MORE soluble in acidic solution because…', opts: ['the acid raises the value of Ksp', 'H⁺ removes OH⁻, pulling it right', 'Mg²⁺ is amphoteric in acid', 'the ionic strength falls sharply'], a: 1, why: 'H⁺ + OH⁻ → H₂O strips a product away; Le Châtelier drags more solid into solution. Any basic-anion salt (carbonates, sulfides, fluorides) does this.' },
  { id: 'equ-020', tier: 3, topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'The Haber process runs at ~450 °C even though K is bigger at 25 °C because…', opts: ['K is in fact larger when hot', 'the rate at 25 °C is far too slow', 'the ammonia decomposes when cold', 'the iron catalyst would melt otherwise'], a: 1, why: 'A thermodynamics-versus-kinetics compromise: sacrifice some K for an acceptable rate, then recover yield with high pressure and NH₃ removal.' },
  { id: 'equ-022', tier: 3, topic: 'equilibrium', skill: 'equilibrium/approximations', q: 'Diluting a weak-acid solution makes its PERCENT ionization…', opts: ['decrease', 'drop to zero', 'stay constant', 'increase'], a: 3, why: 'Ostwald dilution law: Q drops below Ka on dilution → more HA dissociates fractionally (even as pH drifts up toward 7).', misconception: 'Diluting a weak acid raises its percent ionisation while <em>lowering</em> its [H⁺] — the two move in opposite directions, which is why this feels contradictory. Ka is fixed, so as concentration falls the fraction dissociated must rise (Ostwald\'s dilution law); the absolute concentration of H⁺ still drops, and the pH still climbs toward 7. Reading "more ionised" as "more acidic" is the mistake.' },
  { id: 'equ-025', tier: 3, topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'The equilibrium constant is dimensionless because it is properly defined with…', opts: ['mole fractions throughout', 'the masses involved', 'activities, not concentrations', 'the volumes involved'], a: 2, why: 'Each concentration is implicitly divided by the 1 M (or 1 bar) standard state — which is why we can take ln K in ΔG° = −RT ln K.' },
];
